INSERT INTO "cooking_steps" VALUES(1,1,3,'Peel and finely chop the onion. Peel the carrots and cut them into very small cubes. Open the tomatoes and measure all ingredients according to the list.');
INSERT INTO "cooking_steps" VALUES(1,2,2,'Heat the oil in a large saucepan over medium heat. Cook the vegetables for 5 minutes. Add the minced meat, break up the lumps with a spoon, and cook for 6–8 minutes until browned and fully cooked, at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(1,3,0,'Stir the tomato puree into the meat for 1 minute. Add chopped tomatoes, oregano, salt and pepper. Simmer uncovered for 20 minutes, stirring every few minutes. Add a little water if the sauce becomes too thick.');
INSERT INTO "cooking_steps" VALUES(1,4,1,'Bring a large saucepan of water to the boil. Cook the pasta for the time on the packet, stirring at first to prevent sticking. Taste a piece: it should be tender with a little bite. Drain through a colander.');
INSERT INTO "cooking_steps" VALUES(1,5,0,'Divide the cooked pasta between plates and spoon the piping-hot meat sauce over it. Serve immediately. For more servings, use a saucepan large enough for the sauce to simmer without boiling over.');
INSERT INTO "cooking_steps" VALUES(2,1,3,'Peel and chop the onion. Peel and coarsely grate the carrots. Heat a conventional oven to 190 °C and choose an ovenproof dish deep enough for at least three layers.');
INSERT INTO "cooking_steps" VALUES(2,2,2,'Heat the oil in a saucepan. Cook onion and carrot for 5 minutes. Add the meat, break up the lumps and brown for 6–8 minutes. It must be fully cooked and reach at least 75 °C.');
INSERT INTO "cooking_steps" VALUES(2,3,0,'Stir in tomato puree, then add chopped tomatoes, oregano, pepper and half the salt. Simmer the meat sauce for 15 minutes, stirring regularly.');
INSERT INTO "cooking_steps" VALUES(2,4,7,'Melt the butter in another saucepan over medium heat. Whisk in the flour, then gradually whisk in the milk to make a smooth sauce. Simmer for 4 minutes while stirring. Stir in the remaining salt.');
INSERT INTO "cooking_steps" VALUES(2,5,1,'Spread a thin layer of meat sauce in the dish. Alternate lasagne sheets, meat sauce and white sauce; cover the sheets with liquid. Finish with white sauce and grated cheese.');
INSERT INTO "cooking_steps" VALUES(2,6,0,'Bake for about 35–40 minutes. Insert a knife into the middle: the sheets must be tender and the filling bubbling and hot throughout. Cover loosely with foil if the top darkens too early. Rest for 10 minutes before cutting.');
INSERT INTO "cooking_steps" VALUES(3,1,2,'Peel the onion and finely grate it into a bowl. Peel potatoes and carrots. Coarsely grate the carrots for the raw salad and set aside.');
INSERT INTO "cooking_steps" VALUES(3,2,0,'Mix the minced meat with half the salt, pepper, grated onion, egg, flour and milk. Stir into a cohesive mixture and refrigerate for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(3,3,6,'Halve large potatoes so the pieces are similar in size. Cover with water in a saucepan, add the remaining salt and boil for about 15–20 minutes. A small knife should slide through easily. Drain.');
INSERT INTO "cooking_steps" VALUES(3,4,1,'Heat the oil in a frying pan over medium heat. Shape small meatballs with a spoon and fry for about 5–7 minutes per side. Turn carefully. Check for at least 75 °C in the centre and cook longer if needed.');
INSERT INTO "cooking_steps" VALUES(3,5,0,'Serve the fully cooked meatballs with hot potatoes and grated carrot salad. For more servings, fry in batches so the pan is not overcrowded.');
INSERT INTO "cooking_steps" VALUES(4,1,2,'Peel and finely grate the onion. Mix the meat with onion, egg, milk, half the flour, salt and pepper. Refrigerate for 10 minutes. Reserve the rest of the flour for the sauce.');
INSERT INTO "cooking_steps" VALUES(4,2,6,'Cook the rice in a covered saucepan according to the packet. Turn off the heat when the water is absorbed and the rice is tender. Leave covered while finishing the other components.');
INSERT INTO "cooking_steps" VALUES(4,3,1,'Bring water to the boil in a wide saucepan. Shape small meatballs with a spoon, lower them gently into the water and reduce to a gentle simmer. Cook for about 10–12 minutes, depending on size. The centre of a meatball must be fully cooked and at least 75 °C.');
INSERT INTO "cooking_steps" VALUES(4,4,0,'Lift out the cooked meatballs with a slotted spoon. Reserve about 150 ml of cooking water per serving for the sauce. Keep the meatballs warm in a covered dish.');
INSERT INTO "cooking_steps" VALUES(4,5,0,'Melt the butter in a saucepan and stir in curry powder for 30 seconds. Whisk in the reserved flour. Gradually whisk in the measured cooking water and stock powder. Simmer for 5 minutes until smooth.');
INSERT INTO "cooking_steps" VALUES(4,6,0,'Put the meatballs into the sauce and gently heat through for 2–3 minutes. Serve with rice. Stir carefully to keep the meatballs intact.');
INSERT INTO "cooking_steps" VALUES(5,1,3,'Peel and chop the onion. Peel the carrots and cut them into small even cubes. Cook the rice in a separate saucepan according to the packet.');
INSERT INTO "cooking_steps" VALUES(5,2,1,'Cut the meat into even bite-size pieces on a separate board. Wash hands and utensils after handling raw meat. Heat the oil and cook onion and carrot for 5 minutes. Add the meat and brown the pieces on every side.');
INSERT INTO "cooking_steps" VALUES(5,3,0,'Stir in curry powder for 30 seconds. Add coconut milk and salt. Simmer gently for 12–15 minutes, stirring occasionally so the sauce does not stick.');
INSERT INTO "cooking_steps" VALUES(5,4,1,'Check that the thickest piece of meat is fully cooked and at least 75 °C in the centre. Cook longer if necessary. Add a little water if the sauce is very thick.');
INSERT INTO "cooking_steps" VALUES(5,5,0,'Serve the hot curry with the cooked rice. For more servings, use a wider saucepan or cook in batches so the meat cooks evenly.');
INSERT INTO "cooking_steps" VALUES(6,1,2,'Cook the rice using the water quantity and cooking time on the packet. When tender, leave it covered to rest.');
INSERT INTO "cooking_steps" VALUES(6,2,3,'Rinse the broccoli and cut it into small florets. Peel the carrots and thinly slice them. Boil the vegetables in water for 4–6 minutes until tender with a little bite. Drain.');
INSERT INTO "cooking_steps" VALUES(6,3,1,'Cut the meat into even strips on a separate board. Wash hands and utensils. Heat the oil in a frying pan over medium-high heat and cook the meat for 8–12 minutes. Turn regularly; it must be fully cooked and at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(6,4,0,'Add the cooked vegetables to the pan with soy sauce and salt. Stir and heat for 2 minutes. Do not leave cooked rice standing warm for a long time; use it immediately.');
INSERT INTO "cooking_steps" VALUES(6,5,0,'Divide the rice and hot meat-and-vegetable mixture between plates and serve.');
INSERT INTO "cooking_steps" VALUES(7,1,4,'Peel and chop the onion. Rinse the pepper, remove its stalk and seeds and dice the flesh. Rinse and drain the cooked beans. Cook the rice according to the packet.');
INSERT INTO "cooking_steps" VALUES(7,2,1,'Heat the oil in a saucepan. Cook onion and pepper for 5 minutes. Add the meat, break up the lumps and cook for 6–8 minutes until fully cooked, at least 75 °C.');
INSERT INTO "cooking_steps" VALUES(7,3,0,'Stir in paprika, cumin and chilli powder for 30 seconds. Add chopped tomatoes and salt. Simmer for 20 minutes, stirring regularly.');
INSERT INTO "cooking_steps" VALUES(7,4,2,'Stir the cooked drained beans into the saucepan. Simmer for another 8–10 minutes until hot throughout. This recipe uses already cooked beans; never add raw dried beans directly.');
INSERT INTO "cooking_steps" VALUES(7,5,0,'Serve the piping-hot chilli with rice. It should be thick but easy to stir; add a little water if it sticks.');
INSERT INTO "cooking_steps" VALUES(8,1,4,'Peel and chop the onion. Rinse the pepper, remove the stalk and seeds and dice it. Rinse and drain both kinds of cooked beans and the sweetcorn.');
INSERT INTO "cooking_steps" VALUES(8,2,7,'Cook the rice in a separate saucepan according to the packet. Leave covered when the water is absorbed and the rice is tender.');
INSERT INTO "cooking_steps" VALUES(8,3,0,'Heat the oil in a large saucepan. Cook onion and pepper for 5 minutes. Stir in paprika, cumin and chilli powder for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(8,4,0,'Add chopped tomatoes, both kinds of cooked beans, sweetcorn and salt. Simmer for 20 minutes, stirring often. Add a little water if the mixture becomes too thick.');
INSERT INTO "cooking_steps" VALUES(8,5,0,'Check that the vegetables are tender and the beans hot throughout. Serve with rice. Never add raw dried beans directly to this stew.');
INSERT INTO "cooking_steps" VALUES(9,1,4,'Peel and chop the onion. Clean the mushrooms with a brush or a quick rinse, then slice them. Cook the pasta according to the packet, reserving a little cooking water before draining.');
INSERT INTO "cooking_steps" VALUES(9,2,2,'Cut the meat into small even pieces on a separate board, then wash hands and utensils. Heat the oil in a large frying pan. Cook the meat for 8–12 minutes until fully cooked and at least 75 °C in the centre. Transfer to a clean plate.');
INSERT INTO "cooking_steps" VALUES(9,3,0,'Cook onion and mushrooms in the same pan for 6–8 minutes until the mushroom liquid has evaporated. Reduce to medium heat and add cooking cream, salt and pepper.');
INSERT INTO "cooking_steps" VALUES(9,4,0,'Simmer the sauce for 5 minutes. Return the fully cooked meat and heat for another 2 minutes. Fold in the drained pasta; add some reserved cooking water if the sauce is very thick.');
INSERT INTO "cooking_steps" VALUES(9,5,0,'Serve immediately when the entire dish is hot. For more servings, cook the meat in batches rather than crowding the pan.');
INSERT INTO "cooking_steps" VALUES(10,1,3,'Peel and finely chop the onion. Peel and very finely chop the garlic. Grate the Parmesan if necessary.');
INSERT INTO "cooking_steps" VALUES(10,2,0,'Heat the oil in a saucepan over medium heat. Cook the onion for 5 minutes without browning it. Add garlic and stir for 30 seconds; do not let it turn black.');
INSERT INTO "cooking_steps" VALUES(10,3,0,'Add tomatoes, basil, salt and pepper. Simmer uncovered for 20 minutes, stirring occasionally, until slightly thickened.');
INSERT INTO "cooking_steps" VALUES(10,4,1,'Cook the pasta in plenty of water according to the packet. Taste a piece to check that it is tender with a little bite. Drain.');
INSERT INTO "cooking_steps" VALUES(10,5,0,'Fold the pasta into the hot tomato sauce, divide between plates and sprinkle with Parmesan.');
INSERT INTO "cooking_steps" VALUES(11,1,5,'Peel and very finely chop the onion. Reserve half for the sauce. Mix the rest with minced meat, egg, breadcrumbs, half the salt and pepper. Shape small meatballs with damp hands.');
INSERT INTO "cooking_steps" VALUES(11,2,2,'Heat half the oil in a frying pan. Brown the meatballs on all sides for about 6 minutes over medium heat. They need not be fully cooked yet because they finish cooking in the sauce.');
INSERT INTO "cooking_steps" VALUES(11,3,0,'Heat the remaining oil in a wide saucepan and cook the reserved onion for 4 minutes. Add tomatoes, oregano and the remaining salt. Bring to a gentle simmer.');
INSERT INTO "cooking_steps" VALUES(11,4,2,'Add the browned meatballs, cover and simmer gently for 15–20 minutes. Check for at least 75 °C in the centre of one of the largest meatballs. Stir carefully to keep them intact.');
INSERT INTO "cooking_steps" VALUES(11,5,1,'Cook the pasta according to the packet and drain. Serve with the hot tomato sauce and fully cooked meatballs.');
INSERT INTO "cooking_steps" VALUES(12,1,0,'Rinse the vegetables. Peel carrots and ginger. Cut carrot and pepper into thin strips, broccoli into small florets and spring onions into slices. Finely chop garlic and ginger.');
INSERT INTO "cooking_steps" VALUES(12,2,2,'Cut the meat into thin even strips on a separate board. Wash hands and utensils. Heat half the oil in a large frying pan or wok and cook the meat for 8–10 minutes until fully cooked and at least 75 °C. Transfer to a clean plate.');
INSERT INTO "cooking_steps" VALUES(12,3,1,'Cook the noodles for the time on the packet. Drain and loosen with a fork so they do not clump.');
INSERT INTO "cooking_steps" VALUES(12,4,0,'Heat the remaining oil. Stir-fry carrot, broccoli and pepper for 5–6 minutes until tender with a little bite. Add garlic, ginger and spring onions for the last minute.');
INSERT INTO "cooking_steps" VALUES(12,5,0,'Fold the fully cooked meat, noodles and soy sauce into the vegetables. Heat for 2 minutes while stirring gently and serve immediately.');
INSERT INTO "cooking_steps" VALUES(13,1,0,'Rinse lettuce, tomato and cucumber. Shred the lettuce and finely dice tomato and cucumber. Peel and chop the garlic. Mix it with yoghurt and half the salt for a dressing.');
INSERT INTO "cooking_steps" VALUES(13,2,1,'Cut the meat into thin strips on a separate board, then wash hands and utensils. Heat the oil in a frying pan. Cook the meat with paprika and the remaining salt for 8–12 minutes until fully cooked and at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(13,3,2,'Warm the tortillas according to the packet. Keep them covered with a clean tea towel so they remain soft.');
INSERT INTO "cooking_steps" VALUES(13,4,0,'Spread dressing down the middle of each tortilla. Add lettuce, tomato, cucumber and fully cooked meat, leaving a border on both sides.');
INSERT INTO "cooking_steps" VALUES(13,5,0,'Fold the sides in slightly and roll the tortillas tightly around the filling. Serve immediately. Use a clean serving dish for the cooked meat.');
INSERT INTO "cooking_steps" VALUES(14,1,3,'Peel and chop the onion. Rinse lettuce and tomatoes, shred the lettuce and dice the tomatoes. Drain the sweetcorn and arrange the cold toppings in small bowls.');
INSERT INTO "cooking_steps" VALUES(14,2,2,'Heat the oil in a frying pan. Cook the onion for 4 minutes. Add the minced meat, break up the lumps and cook for 6–8 minutes until fully cooked and at least 75 °C. Stir in paprika, cumin, chilli and salt.');
INSERT INTO "cooking_steps" VALUES(14,3,0,'Add about 20 ml water per serving to the meat. Simmer for 3–5 minutes until almost evaporated, while keeping the filling juicy.');
INSERT INTO "cooking_steps" VALUES(14,4,1,'Warm the taco shells according to the packet, usually for a few minutes in the oven. Watch carefully because they darken quickly.');
INSERT INTO "cooking_steps" VALUES(14,5,0,'Fill the shells with a little lettuce and hot meat. Top with tomato, sweetcorn, cheese and creme fraiche. Eat immediately while the shells are crisp.');
INSERT INTO "cooking_steps" VALUES(15,1,4,'Peel and chop the onion. Rinse and drain the cooked black beans. Cook the rice in a separate saucepan according to the packet.');
INSERT INTO "cooking_steps" VALUES(15,2,0,'Heat the oil in a saucepan and cook the onion for 5 minutes. Stir in paprika and cumin for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(15,3,2,'Add cooked beans, chopped tomatoes and salt. Simmer uncovered for 12–15 minutes, stirring occasionally, until hot and thick enough to stay inside a tortilla.');
INSERT INTO "cooking_steps" VALUES(15,4,1,'Warm the tortillas according to the packet until flexible. Put cooked rice, hot bean filling and cheese in the middle of each.');
INSERT INTO "cooking_steps" VALUES(15,5,0,'Fold both sides in, fold the bottom over the filling and roll tightly. Put seam-side down on a plate and serve immediately.');
INSERT INTO "cooking_steps" VALUES(16,1,3,'Heat a conventional oven to 210 °C. Scrub the potatoes, cut into wedges and toss with a little more than half the oil and half the salt. Spread on baking paper and bake for 30–35 minutes, turning after 20 minutes, until tender and golden.');
INSERT INTO "cooking_steps" VALUES(16,2,7,'Peel the onion and cut it into thin rings. Rinse lettuce, tomato and cucumber. Shred the lettuce and slice tomato and cucumber.');
INSERT INTO "cooking_steps" VALUES(16,3,1,'Shape the minced meat into flat patties and season with the remaining salt and pepper. Heat the remaining oil in a frying pan and cook the patties for about 4–6 minutes per side, depending on thickness. Check for at least 75 °C in the centre; they must be fully cooked.');
INSERT INTO "cooking_steps" VALUES(16,4,2,'Split the buns and warm them for 2–3 minutes in the oven or a toaster. Watch so they do not burn.');
INSERT INTO "cooking_steps" VALUES(16,5,0,'Spread mustard and ketchup on the bun bases. Add lettuce, a fully cooked patty, tomato, cucumber and onion. Add the bun tops and serve with hot potato wedges.');
INSERT INTO "cooking_steps" VALUES(17,1,0,'Rinse lettuce, tomato and cucumber. Shred the lettuce and finely dice the rest. Peel and very finely chop the garlic. Squeeze the lemon juice.');
INSERT INTO "cooking_steps" VALUES(17,2,6,'Mix yoghurt with garlic, lemon juice and salt. Refrigerate the dressing while cooking the hot components.');
INSERT INTO "cooking_steps" VALUES(17,3,2,'Heat the ready-made falafel on baking paper in the oven, using the packet temperature and time, typically 180–200 °C for 12–18 minutes. Turn if the packet instructs. They must be hot throughout and crisp outside.');
INSERT INTO "cooking_steps" VALUES(17,4,1,'Warm the pitta bread according to the packet. Carefully cut a pocket in one side with a bread knife, without cutting through the far side.');
INSERT INTO "cooking_steps" VALUES(17,5,0,'Fill the bread with lettuce, vegetables, hot falafel and dressing. Divide all components evenly between servings and serve immediately.');
INSERT INTO "cooking_steps" VALUES(18,1,2,'Heat a conventional oven to 180 °C. Peel the potatoes, cut large ones in half and cover with water in a saucepan. Boil for 15–20 minutes until a knife slides through easily, then drain.');
INSERT INTO "cooking_steps" VALUES(18,2,1,'Check the salmon for bones with your fingers. Oil an ovenproof dish, add the fish and season with half the salt and the pepper. Slice the lemon and arrange on top. Bake for about 15–20 minutes until hot throughout and easy to separate into flakes.');
INSERT INTO "cooking_steps" VALUES(18,3,3,'Rinse the broccoli and cut it into small florets. Boil in water for 4–6 minutes until tender with a little bite, then drain.');
INSERT INTO "cooking_steps" VALUES(18,4,0,'Divide the hot fish, potatoes and vegetables between plates. Sprinkle the remaining salt on the potatoes and serve with the baked lemon slices.');
INSERT INTO "cooking_steps" VALUES(19,1,3,'Peel and finely grate the onion. Peel potatoes and carrots. Coarsely grate the carrots and toss with lemon juice for the salad.');
INSERT INTO "cooking_steps" VALUES(19,2,1,'Check the raw fish carefully for bones. Chop very finely with a knife or briefly in a food processor. Mix with onion, egg, flour, milk, half the salt and pepper to make a firm fish mixture. Refrigerate for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(19,3,6,'Cover the potatoes with water, add the remaining salt and boil for 15–20 minutes until a knife slides through easily. Drain.');
INSERT INTO "cooking_steps" VALUES(19,4,1,'Heat the oil in a frying pan over medium heat. Shape small fish cakes with a spoon and fry for about 4–5 minutes on each side. They must be firm, lightly golden and hot throughout, at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(19,5,0,'Serve the fish cakes with potatoes and the cold carrot salad. Keep the fish mixture refrigerated until frying and wash utensils after handling raw fish.');
INSERT INTO "cooking_steps" VALUES(20,1,3,'Peel and chop the onion. Peel the potatoes and cut into small cubes. Split the leeks lengthways, rinse thoroughly between the layers and cut into thin rings.');
INSERT INTO "cooking_steps" VALUES(20,2,0,'Melt the butter in a large saucepan over medium heat. Cook onion and leek for 5 minutes without browning.');
INSERT INTO "cooking_steps" VALUES(20,3,1,'Add potatoes, stock powder and about 250 ml water per serving. Cover and simmer for 20–25 minutes until the potatoes are completely tender.');
INSERT INTO "cooking_steps" VALUES(20,4,0,'Mash the vegetables in the pan with a potato masher or blend carefully with a hand blender. Stir in cooking cream, salt and pepper and heat for 3 minutes. Add a little water if the soup is too thick.');
INSERT INTO "cooking_steps" VALUES(20,5,0,'Serve the piping-hot soup with bread. With a hand blender, keep the blade submerged before starting so hot liquid does not splash.');
INSERT INTO "cooking_steps" VALUES(21,1,3,'Peel and chop the onion. Peel the carrots and cut into small cubes. Heat the oil in a large saucepan and cook the vegetables for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(21,2,0,'Add chopped tomatoes, stock powder, basil and about 200 ml water per serving. Cover and simmer for 15 minutes until the carrots are tender.');
INSERT INTO "cooking_steps" VALUES(21,3,2,'Add the pasta to the soup and cook for the time on the packet. Stir along the bottom often and add water if the pasta absorbs too much liquid. The pasta must be tender.');
INSERT INTO "cooking_steps" VALUES(21,4,0,'Stir in cooking cream and salt. Heat gently for 3 minutes without a hard boil. Divide between deep plates and serve hot.');
INSERT INTO "cooking_steps" VALUES(22,1,3,'Cut the bacon into small pieces and fry in an ovenproof frying pan over medium heat for 6–8 minutes until cooked through. Remove the bacon, leaving a little rendered fat in the pan.');
INSERT INTO "cooking_steps" VALUES(22,2,2,'Whisk the eggs with milk, salt and pepper in a bowl. Pour into the pan over low heat. Let the base set for about 5 minutes without stirring.');
INSERT INTO "cooking_steps" VALUES(22,3,0,'Cover the pan and let the eggs set for another 10–15 minutes over low heat. The centre must be firm with no liquid egg. Use several pans for more servings.');
INSERT INTO "cooking_steps" VALUES(22,4,0,'Rinse and slice the tomatoes. Rinse and snip the chives. Arrange bacon, tomato and chives on the cooked eggs and serve with rye bread.');
INSERT INTO "cooking_steps" VALUES(23,1,2,'Rinse fresh spinach and drain. If using frozen spinach, thaw and drain it first. Heat the oil in a large frying pan and cook the spinach for 3–5 minutes until hot and excess liquid has evaporated.');
INSERT INTO "cooking_steps" VALUES(23,2,4,'Whisk the eggs with milk, salt and pepper. Pour over the spinach and sprinkle the cheese evenly on top.');
INSERT INTO "cooking_steps" VALUES(23,3,0,'Reduce to low heat, cover and let the omelette set for 8–12 minutes. The middle must be firm without raw egg; allow longer for a thick omelette.');
INSERT INTO "cooking_steps" VALUES(23,4,0,'Carefully fold the omelette with a spatula or cut into pieces in the pan. Serve with bread. For more servings, make several omelettes rather than one very thick one.');
INSERT INTO "cooking_steps" VALUES(24,1,1,'Peel the potatoes, cut into bite-size cubes and boil in water for about 10–12 minutes until almost tender. Drain.');
INSERT INTO "cooking_steps" VALUES(24,2,3,'Peel and chop the onion. Slice the sausages. Heat the oil in a wide saucepan and cook the onion for 4 minutes. Add sausages and cook for another 4 minutes.');
INSERT INTO "cooking_steps" VALUES(24,3,0,'Stir in paprika and tomato puree and cook, stirring, for 1 minute. Add milk, cooking cream, salt and pepper.');
INSERT INTO "cooking_steps" VALUES(24,4,0,'Carefully fold the potatoes into the sauce. Simmer for 8–10 minutes until the potatoes are completely tender and sausages hot throughout. Stir along the bottom and add a little water if the sauce is too thick.');
INSERT INTO "cooking_steps" VALUES(24,5,0,'Serve piping hot straight from the saucepan. The potatoes may release some starch to thicken the sauce but should still hold their shape.');
INSERT INTO "cooking_steps" VALUES(25,1,4,'Peel and chop the onion. Clean and quarter the mushrooms. Rinse, deseed and dice the pepper. Cook the rice according to the packet.');
INSERT INTO "cooking_steps" VALUES(25,2,1,'Use a sharp knife to remove visible sinews and the shiny membrane from the tenderloin. Slice the meat. Heat half the oil in a saucepan and brown small batches for about 2 minutes per side. Transfer to a clean plate.');
INSERT INTO "cooking_steps" VALUES(25,3,0,'Heat the remaining oil. Cook onion, mushrooms and pepper for 6–8 minutes until mushroom liquid has evaporated. Stir in paprika for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(25,4,0,'Add chopped tomatoes, cooking cream, salt and pepper. Return the meat and simmer gently for about 10–15 minutes. Check a thick piece is cooked throughout; at least 75 °C is a simple check.');
INSERT INTO "cooking_steps" VALUES(25,5,0,'Serve the hot stew with rice. Keep the sauce at a gentle simmer so vigorous boiling does not dry out the meat.');
INSERT INTO "cooking_steps" VALUES(26,1,3,'Peel the potatoes and boil in water with half the salt for 15–20 minutes until tender. Drain and keep warm under a lid.');
INSERT INTO "cooking_steps" VALUES(26,2,2,'Peel and thinly slice the onions. Melt half the butter in a frying pan over medium heat. Cook the onions slowly for 15–20 minutes, stirring often, until soft and golden. Remove from the pan.');
INSERT INTO "cooking_steps" VALUES(26,3,1,'Shape the minced meat into flat patties. Season with the remaining salt and pepper. Heat the oil in the pan and cook for about 4–6 minutes per side. Check for at least 75 °C in the centre and keep warm.');
INSERT INTO "cooking_steps" VALUES(26,4,0,'Melt the remaining butter in the pan. Stir in the flour. Gradually whisk in milk and about 75 ml water per serving, then add stock powder. Simmer for 5 minutes while stirring until smooth.');
INSERT INTO "cooking_steps" VALUES(26,5,0,'Spoon the soft onions over the patties. Serve with boiled potatoes and hot gravy.');
INSERT INTO "cooking_steps" VALUES(27,1,4,'Peel the potatoes and boil in water with half the salt for 15–20 minutes until tender. Drain.');
INSERT INTO "cooking_steps" VALUES(27,2,1,'Shape the minced meat into flat patties. Season with the remaining salt and pepper. Beat the egg in a deep plate and put breadcrumbs in another. Coat each patty first in egg, then breadcrumbs.');
INSERT INTO "cooking_steps" VALUES(27,3,1,'Heat the oil in a frying pan over medium heat. Fry the patties for about 6–8 minutes per side, until golden and at least 75 °C in the centre. Lower the heat if the coating darkens before the meat is cooked.');
INSERT INTO "cooking_steps" VALUES(27,4,6,'Melt the butter in a saucepan. Stir in flour, then gradually whisk in milk. Simmer for 4 minutes while stirring. Add the peas and heat for 5 minutes until hot throughout.');
INSERT INTO "cooking_steps" VALUES(27,5,0,'Serve the patties with potatoes and creamed peas. Fry in batches for more servings so the pan is not overcrowded.');
INSERT INTO "cooking_steps" VALUES(28,1,2,'Peel the potatoes, cover with water and add the salt. Boil for 15–20 minutes until a knife slides through easily. Drain.');
INSERT INTO "cooking_steps" VALUES(28,2,1,'Put the raw pork sausage in a wide saucepan of water. Heat to just below boiling and simmer very gently for 15 minutes. Lift it out carefully with two utensils so it does not break.');
INSERT INTO "cooking_steps" VALUES(28,3,1,'Heat the oil in a frying pan over medium heat. Fry the poached sausage for 8–12 minutes, turning several times. The skin must be golden and the thickest part fully cooked, at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(28,4,3,'Put the prepared red cabbage in a small saucepan with a little water. Cover and heat gently for about 8 minutes, stirring occasionally, until hot throughout.');
INSERT INTO "cooking_steps" VALUES(28,5,0,'Serve sausage, potatoes and red cabbage with mustard on the side. Raw sausage must be fully cooked even if the skin colours quickly.');
INSERT INTO "cooking_steps" VALUES(29,1,2,'Peel and finely grate the onion. Mix the minced meat with onion, egg, oats, milk, half the salt and pepper. Refrigerate for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(29,2,6,'Cook the bulgur using the water quantity and time on the packet. Leave covered when tender and fluff with a fork.');
INSERT INTO "cooking_steps" VALUES(29,3,0,'Rinse and coarsely grate the cucumber. Squeeze out some liquid with clean hands. Mix with yoghurt and the remaining salt, then refrigerate.');
INSERT INTO "cooking_steps" VALUES(29,4,1,'Heat the oil in a frying pan over medium heat. Shape small meatballs and fry for 5–7 minutes per side. Check for at least 75 °C in the thickest one; no raw mixture may remain inside.');
INSERT INTO "cooking_steps" VALUES(29,5,0,'Serve the fully cooked meatballs with hot bulgur and cold cucumber yoghurt. Use clean serving dishes and utensils for cooked meat.');
INSERT INTO "cooking_steps" VALUES(30,1,2,'Peel the potatoes and boil in water with the salt for 15–20 minutes until a knife slides through easily. Drain.');
INSERT INTO "cooking_steps" VALUES(30,2,1,'Read the fish packet for cooking time and whether to cook from frozen. Heat the oil in a frying pan over medium heat. Fry for typically 4–6 minutes per side, or the longer time on the packet. The coating should be golden and the fish hot and firm in the centre.');
INSERT INTO "cooking_steps" VALUES(30,3,3,'Boil the peas in a small saucepan of water for 3–5 minutes until hot throughout. Drain and cut the lemon into wedges.');
INSERT INTO "cooking_steps" VALUES(30,4,0,'Serve the fish immediately with potatoes, peas, lemon and remoulade. Leave space between fillets in the pan so the coating becomes crisp.');
INSERT INTO "cooking_steps" VALUES(31,1,2,'Heat a conventional oven to 200 °C. Peel potatoes and root vegetables and cut into small even sticks or cubes. Toss with oil, thyme and half the salt. Spread on a baking tray lined with baking paper.');
INSERT INTO "cooking_steps" VALUES(31,2,0,'Bake the vegetables for 20 minutes, then turn them. They should be starting to soften; large pieces need longer.');
INSERT INTO "cooking_steps" VALUES(31,3,1,'Check the fish for bones. Put it on top of the vegetables, season with the remaining salt and pepper and add lemon slices. Bake for another 12–18 minutes until the fish is hot throughout and flakes easily.');
INSERT INTO "cooking_steps" VALUES(31,4,0,'Pierce potatoes and root vegetables to check they are tender. Lift out the fish and keep warm if the vegetables need more time. Serve everything hot.');
INSERT INTO "cooking_steps" VALUES(32,1,1,'Cook the rice according to the packet. Spread it on a large clean dish for 5–10 minutes to let some steam escape. Use immediately in this dish; do not leave it standing warm for a long time.');
INSERT INTO "cooking_steps" VALUES(32,2,0,'Peel and finely dice the carrots. Rinse and slice the spring onions. Lightly beat the eggs in a bowl.');
INSERT INTO "cooking_steps" VALUES(32,3,2,'Heat half the oil in a large frying pan. Add the eggs and stir slowly for 2–3 minutes until completely set as scrambled eggs. Transfer to a clean plate.');
INSERT INTO "cooking_steps" VALUES(32,4,0,'Heat the remaining oil. Cook the carrots for 5 minutes. Add peas and spring onions and cook for another 3 minutes until the vegetables are hot throughout.');
INSERT INTO "cooking_steps" VALUES(32,5,0,'Fold freshly cooked rice, cooked eggs and soy sauce into the vegetables. Stir-fry for 3–4 minutes until everything is hot. Serve immediately.');
INSERT INTO "cooking_steps" VALUES(33,1,5,'Peel and chop the onion. Peel garlic and ginger and finely chop both. Rinse the lentils thoroughly in a sieve. Cook the rice separately according to the packet.');
INSERT INTO "cooking_steps" VALUES(33,2,0,'Heat the oil in a saucepan. Cook the onion for 5 minutes. Stir in garlic, ginger, curry powder and cumin for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(33,3,1,'Add rinsed red lentils, coconut milk, chopped tomatoes and about 100 ml water per serving. Simmer gently for 20–25 minutes. Stir along the bottom often and add water if it becomes too dry.');
INSERT INTO "cooking_steps" VALUES(33,4,0,'Check that the lentils are completely soft with no hard centre. Stir in the salt. Serve the hot dhal with rice; it should be thick and soft rather than dry.');
INSERT INTO "cooking_steps" VALUES(34,1,4,'Peel and chop onion and garlic. Rinse and drain the cooked chickpeas. Rinse fresh spinach; frozen spinach can go straight into the pan later. Cook the rice according to the packet.');
INSERT INTO "cooking_steps" VALUES(34,2,0,'Heat the oil in a saucepan. Cook the onion for 5 minutes. Add garlic and curry powder and stir for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(34,3,1,'Add coconut milk and the cooked drained chickpeas. Simmer for 10 minutes. Do not add raw dried chickpeas directly to this dish.');
INSERT INTO "cooking_steps" VALUES(34,4,2,'Stir in spinach. Simmer for 5–8 minutes until fresh leaves wilt or frozen spinach is completely thawed and hot throughout. Stir in salt and add water if the sauce is very thick.');
INSERT INTO "cooking_steps" VALUES(34,5,0,'Serve the curry and rice hot. Check that the chickpeas and vegetables are hot all the way through.');
INSERT INTO "cooking_steps" VALUES(35,1,5,'Heat a conventional oven to 190 °C. Peel and chop the onion. Peel and grate the carrots; rinse and finely dice the courgette. Rinse and drain the cooked lentils.');
INSERT INTO "cooking_steps" VALUES(35,2,0,'Heat the oil in a saucepan and cook onion, carrot and courgette for 7 minutes. Add lentils, tomatoes, oregano, half the salt and pepper. Simmer for 15 minutes.');
INSERT INTO "cooking_steps" VALUES(35,3,7,'Melt the butter in another saucepan. Whisk in flour, then gradually whisk in milk. Simmer for 4 minutes while stirring. Stir in the remaining salt.');
INSERT INTO "cooking_steps" VALUES(35,4,1,'Spread a little vegetable sauce in an ovenproof dish. Alternate lasagne sheets, vegetable sauce and white sauce in at least three layers. Cover all sheets with sauce. Finish with white sauce and grated cheese.');
INSERT INTO "cooking_steps" VALUES(35,5,0,'Bake for 35–40 minutes until a knife passes through tender sheets and the centre is hot throughout. Rest for 10 minutes before serving.');
INSERT INTO "cooking_steps" VALUES(36,1,1,'Heat a conventional oven to 200 °C. Scrub large potatoes and prick the skins several times with a fork. Bake on baking paper for about 55–70 minutes until soft when pressed and easily pierced with a knife.');
INSERT INTO "cooking_steps" VALUES(36,2,4,'Peel and chop the onion. Rinse and drain cooked beans and sweetcorn. Heat the oil in a saucepan and cook the onion for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(36,3,0,'Stir in paprika. Add tomatoes, beans, sweetcorn and half the salt. Simmer for 15 minutes until the filling is hot and thick, stirring regularly.');
INSERT INTO "cooking_steps" VALUES(36,4,0,'Cut a cross in each baked potato. Using a clean tea towel, gently squeeze the sides to open the top. Sprinkle the remaining salt over the potato flesh.');
INSERT INTO "cooking_steps" VALUES(36,5,0,'Add hot bean filling and creme fraiche to the potatoes. Serve immediately and take care with the hot steam when opening them.');
INSERT INTO "cooking_steps" VALUES(37,1,1,'Rinse the rice and put it in a heavy-based saucepan with about 75 ml water per serving. Cook, stirring, for 2–3 minutes until much of the water is absorbed.');
INSERT INTO "cooking_steps" VALUES(37,2,2,'Add the milk and heat slowly while stirring. Reduce to very low heat as soon as the liquid begins to boil.');
INSERT INTO "cooking_steps" VALUES(37,3,0,'Half-cover with a lid. Simmer very gently for about 35–45 minutes, stirring the bottom and sides thoroughly every few minutes. The rice must be tender and the pudding thick; add water if it sticks.');
INSERT INTO "cooking_steps" VALUES(37,4,0,'Stir in the salt. Mix sugar and cinnamon in a small bowl. Serve hot with cinnamon sugar and a small portion of the butter on each serving. Eat immediately and refrigerate leftovers promptly after a short release of steam.');
INSERT INTO "cooking_steps" VALUES(38,1,3,'Rinse and core the apples, then finely dice the flesh. Reserve half for serving and use the rest in the saucepan.');
INSERT INTO "cooking_steps" VALUES(38,2,2,'Put oats, milk, salt and the first half of the apple in a heavy-based saucepan. Heat over medium heat while stirring.');
INSERT INTO "cooking_steps" VALUES(38,3,0,'Simmer for 5–7 minutes, stirring often to prevent burning. The porridge should be soft and the apple lightly tender; add water if it is too thick.');
INSERT INTO "cooking_steps" VALUES(38,4,0,'Divide between bowls and top with the remaining apple and cinnamon. Serve warm.');
INSERT INTO "cooking_steps" VALUES(39,1,2,'Whisk flour, milk, egg and salt into a smooth batter without lumps. Leave to rest for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(39,2,4,'Gently melt the butter. Stir half into the batter and reserve the rest to brush the pan between pancakes.');
INSERT INTO "cooking_steps" VALUES(39,3,0,'Heat a frying pan over medium heat and brush with a little reserved fat. Pour in a thin layer of batter and tilt the pan to spread it.');
INSERT INTO "cooking_steps" VALUES(39,4,0,'Cook each pancake for about 1–2 minutes on the first side. Turn when the surface is almost set and the edge releases. Cook the second side for about 1 minute until golden.');
INSERT INTO "cooking_steps" VALUES(39,5,0,'Put cooked pancakes on a plate. Continue with the remaining batter and serve with sugar. More servings mean more pancakes and a longer total frying time.');
INSERT INTO "cooking_steps" VALUES(40,1,1,'Peel the potatoes and cut into even cubes. Boil in unsalted water for 15–20 minutes until completely tender. Drain and leave to steam dry for 1 minute.');
INSERT INTO "cooking_steps" VALUES(40,2,2,'Dice the bacon and fry over medium heat for 6–8 minutes until cooked through and lightly crisp. Remove it, leaving the fat in the pan.');
INSERT INTO "cooking_steps" VALUES(40,3,3,'Peel and thinly slice the onions. Cook in the bacon fat over medium heat for 12–15 minutes until soft and golden. Stir often and lower the heat if they darken.');
INSERT INTO "cooking_steps" VALUES(40,4,4,'Heat the milk in a small saucepan. Mash the hot potatoes with a potato masher. Gradually stir in butter and warm milk, then salt and pepper. Do not use a hand blender because it can make the mash gluey.');
INSERT INTO "cooking_steps" VALUES(40,5,0,'Serve the hot mash topped with onions and bacon, with drained pickled beetroot on the side.');
INSERT INTO "cooking_steps" VALUES(41,1,2,'Peel the potatoes and cut into even cubes. Boil in unsalted water for 15–20 minutes until completely tender. Drain and leave to steam dry for 1 minute.');
INSERT INTO "cooking_steps" VALUES(41,2,3,'Heat the milk in a small saucepan. Mash the potatoes, gradually stir in butter and hot milk and add salt and pepper.');
INSERT INTO "cooking_steps" VALUES(41,3,1,'Heat the oil in a frying pan over medium heat. Fry the sausages for 8–10 minutes, turning regularly, until hot throughout and lightly golden. Follow the packet if the product needs longer.');
INSERT INTO "cooking_steps" VALUES(41,4,5,'Boil peas in a small saucepan of water for 3–5 minutes until hot throughout. Drain.');
INSERT INTO "cooking_steps" VALUES(41,5,0,'Serve sausages, mash and peas with mustard. Keep the mash warm under a lid if the other components are not ready at the same time.');
INSERT INTO "cooking_steps" VALUES(42,1,2,'Heat a conventional oven to 200 °C. Peel and dice the potatoes and boil in unsalted water for 15–20 minutes until completely tender. Drain.');
INSERT INTO "cooking_steps" VALUES(42,2,3,'Peel and chop the onion. Peel and finely dice the carrots. Heat the oil in a saucepan and cook the vegetables for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(42,3,1,'Add the minced meat, break up the lumps with a spoon and cook for 6–8 minutes until fully cooked and at least 75 °C. Stir in tomato puree and thyme.');
INSERT INTO "cooking_steps" VALUES(42,4,0,'Add stock powder, peas, half the salt, pepper and about 100 ml water per serving. Simmer for 10 minutes until the carrots are tender and the filling is not watery.');
INSERT INTO "cooking_steps" VALUES(42,5,8,'Heat the milk. Mash the potatoes with butter, hot milk and the remaining salt. Spread the meat filling in an ovenproof dish and cover evenly with mash. Mark the top with a fork.');
INSERT INTO "cooking_steps" VALUES(42,6,0,'Bake for 20–25 minutes until the top is lightly golden and the filling bubbles at the edges. Rest for 5 minutes before serving.');
INSERT INTO "cooking_steps" VALUES(43,1,1,'Heat a conventional oven to 190 °C. Line a tart tin with the pastry, press it up the sides and prick the base with a fork. Bake the empty case for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(43,2,3,'Split the leeks lengthways and rinse thoroughly between the layers. Slice into rings. Heat half the oil and cook the leeks for 5 minutes until soft. Remove from the pan.');
INSERT INTO "cooking_steps" VALUES(43,3,2,'Cut the meat into small even cubes on a separate board, then wash hands and utensils. Fry in the remaining oil for 8–10 minutes until fully cooked and at least 75 °C. Spread meat and vegetables in the partly baked case.');
INSERT INTO "cooking_steps" VALUES(43,4,5,'Whisk together eggs, milk, salt and pepper. Stir in cheese and pour over the filling so it flows between the pieces.');
INSERT INTO "cooking_steps" VALUES(43,5,0,'Bake for 25–30 minutes until the egg is firm in the centre and the top golden. Rest for 5 minutes before cutting.');
INSERT INTO "cooking_steps" VALUES(44,1,1,'Heat a conventional oven to 190 °C. Line a tart tin with the pastry, press up the sides and prick the base with a fork. Bake the empty case for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(44,2,2,'Split the leeks lengthways and rinse thoroughly between the layers. Cut into thin rings. Heat the oil in a frying pan and cook for 8–10 minutes over medium heat until soft and excess liquid has evaporated.');
INSERT INTO "cooking_steps" VALUES(44,3,4,'Whisk eggs with milk, salt, pepper and nutmeg. Stir in cheese. Spread the cooked vegetables in the pastry case and pour over the egg mixture.');
INSERT INTO "cooking_steps" VALUES(44,4,0,'Bake for about 25–30 minutes. The centre must be firm without liquid egg and the top lightly golden. Rest for 5 minutes before serving.');
INSERT INTO "cooking_steps" VALUES(45,1,1,'Heat a conventional oven to 230 °C with an empty baking tray inside. Roll the dough on baking paper into an even, fairly thin base. Use several bases for more servings.');
INSERT INTO "cooking_steps" VALUES(45,2,5,'Mix tomato passata with oil, oregano and salt. Clean and thinly slice the mushrooms. Cut ham into strips and grate or tear the mozzarella.');
INSERT INTO "cooking_steps" VALUES(45,3,5,'Spread a thin layer of sauce on the base, leaving a border. Arrange ham, mushrooms and cheese evenly. Avoid a thick topping that makes the centre wet.');
INSERT INTO "cooking_steps" VALUES(45,4,0,'Slide the pizza and its paper onto the hot tray. Bake for about 12–18 minutes until the edge is golden, the base cooked and the cheese bubbling. Follow the packet temperature if it differs substantially.');
INSERT INTO "cooking_steps" VALUES(45,5,0,'Rest the pizza for 2 minutes, then cut into pieces. Bake one tray at a time for the most even heat.');
INSERT INTO "cooking_steps" VALUES(46,1,1,'Heat a conventional oven to 210 °C. Roll the dough into a rectangle on baking paper. Cut the ham into small pieces.');
INSERT INTO "cooking_steps" VALUES(46,2,4,'Spread a thin layer of tomato passata over the dough. Sprinkle with oregano, ham and cheese, leaving a narrow border along one long side.');
INSERT INTO "cooking_steps" VALUES(46,3,0,'Roll tightly from the opposite long side. Use a sharp knife to cut slices about 2–3 cm thick. Put the rolls on baking paper with space between them.');
INSERT INTO "cooking_steps" VALUES(46,4,6,'Lightly beat the egg and brush the rolls. Bake for 15–20 minutes until the dough is golden and cooked in the middle and the cheese bubbles.');
INSERT INTO "cooking_steps" VALUES(46,5,0,'Cool briefly on a rack before serving. For packed lunches, cool quickly and refrigerate.');
INSERT INTO "cooking_steps" VALUES(47,1,2,'Gently melt the butter in a saucepan. Add milk and check the mixture is only lukewarm, no more than about 37 °C. Crumble yeast into a bowl and stir in the warm liquid until dissolved.');
INSERT INTO "cooking_steps" VALUES(47,2,0,'Add flour and salt and knead for about 8 minutes until smooth and elastic. Cover the bowl with a clean tea towel and rise in a warm place for 30 minutes.');
INSERT INTO "cooking_steps" VALUES(47,3,0,'Heat a conventional oven to 210 °C. Divide the dough into manageable pieces, roll out and cut triangles. Halve large sausages.');
INSERT INTO "cooking_steps" VALUES(47,4,0,'Spread a little ketchup on the wide end of each triangle, add a sausage piece and roll towards the point. Put point-side down on baking paper and rise for 15 minutes.');
INSERT INTO "cooking_steps" VALUES(47,5,5,'Beat the egg and brush the rolls. Bake for about 15–20 minutes until golden and the bread is cooked throughout. Cool briefly before serving.');
INSERT INTO "cooking_steps" VALUES(48,1,4,'Peel and chop the onion. Rinse and deseed the pepper, then finely dice it. Rinse and drain the cooked beans.');
INSERT INTO "cooking_steps" VALUES(48,2,0,'Heat half the oil in a frying pan. Cook onion and pepper for 6–7 minutes until tender. Add beans, cumin and salt. Roughly mash with a fork and heat for 3 minutes.');
INSERT INTO "cooking_steps" VALUES(48,3,0,'Spread bean filling and cheese over one half of each tortilla and fold the other half over. Keep the filling thin enough for the cheese to melt.');
INSERT INTO "cooking_steps" VALUES(48,4,1,'Brush a clean frying pan with the remaining oil. Cook the filled tortillas over medium heat for about 2–3 minutes per side until golden, with hot filling and melted cheese.');
INSERT INTO "cooking_steps" VALUES(48,5,0,'Cut into triangles and serve immediately with salsa on the side. Cook in batches without stacking them in the pan.');
INSERT INTO "cooking_steps" VALUES(49,1,4,'Heat a conventional oven to 200 °C. Peel and chop the onion. Rinse and drain the cooked beans.');
INSERT INTO "cooking_steps" VALUES(49,2,2,'Heat the oil in a frying pan. Cook the onion for 4 minutes, add the minced meat and break up the lumps. Cook for 6–8 minutes until fully cooked and at least 75 °C. Stir in paprika, cumin and salt.');
INSERT INTO "cooking_steps" VALUES(49,3,0,'Stir beans and half the salsa into the meat and heat for 3 minutes. The filling should be hot and fairly dry so the chips do not become soggy.');
INSERT INTO "cooking_steps" VALUES(49,4,0,'Spread chips in a wide ovenproof dish and top with hot filling and cheese. Bake for 8–10 minutes until the cheese melts and bubbles. Watch so the chips do not burn.');
INSERT INTO "cooking_steps" VALUES(49,5,0,'Serve immediately with the remaining salsa and creme fraiche on the side. For more servings, use several wide dishes rather than one deep dish.');
INSERT INTO "cooking_steps" VALUES(50,1,3,'Fry bacon over medium heat for 6–8 minutes until cooked through and crisp. Transfer to a clean plate and pour off excess fat.');
INSERT INTO "cooking_steps" VALUES(50,2,2,'Cut the meat into thin even slices on a separate board, then wash hands and utensils. Heat the oil, season the meat with salt and pepper and fry for 8–12 minutes until fully cooked and at least 75 °C. Transfer to a clean plate.');
INSERT INTO "cooking_steps" VALUES(50,3,0,'Rinse lettuce and tomato, shred the lettuce and thinly slice the tomatoes. Mix mayonnaise and mustard.');
INSERT INTO "cooking_steps" VALUES(50,4,1,'Toast the bread in a toaster or a dry frying pan until lightly golden. Spread dressing on the slices.');
INSERT INTO "cooking_steps" VALUES(50,5,0,'Assemble sandwiches with lettuce, tomato, hot meat and bacon. Cut into triangles with a sharp knife and serve immediately.');
INSERT INTO "cooking_steps" VALUES(51,1,0,'Rinse and slice tomato and cucumber. Arrange bread slices in pairs for the base and top of each sandwich.');
INSERT INTO "cooking_steps" VALUES(51,2,4,'Spread a thin layer of butter on the outside of the bread. Spread a little mustard on the inside of each base.');
INSERT INTO "cooking_steps" VALUES(51,3,0,'Put ham and cheese on the bases and cover with the other slices, buttered sides facing out.');
INSERT INTO "cooking_steps" VALUES(51,4,1,'Toast in a sandwich maker or a frying pan over medium heat. In a pan, cook for about 3–4 minutes per side with gentle pressure. The bread must be golden and the cheese melted.');
INSERT INTO "cooking_steps" VALUES(51,5,0,'Cut each sandwich in half and serve immediately with tomato and cucumber. Let the hot cheese cool briefly before taking a bite.');
INSERT INTO "cooking_steps" VALUES(52,1,3,'Peel and very finely chop the red onion. Thoroughly drain tuna and sweetcorn. Rinse and slice the cucumber. Squeeze the lemon juice.');
INSERT INTO "cooking_steps" VALUES(52,2,0,'Flake the drained tuna into a bowl with a fork. Fold in sweetcorn and the finely chopped onion.');
INSERT INTO "cooking_steps" VALUES(52,3,4,'Mix mayonnaise, creme fraiche, lemon juice, salt and pepper. Fold the dressing into the tuna mixture until cohesive but not runny.');
INSERT INTO "cooking_steps" VALUES(52,4,0,'Spread tuna salad on rye bread and serve with cucumber. Refrigerate if not serving immediately.');
INSERT INTO "cooking_steps" VALUES(53,1,1,'Cover the eggs with cold water in a saucepan. Bring to the boil, reduce slightly and boil for about 9–10 minutes. Cool immediately with cold water, peel and roughly chop. The yolks must be firm.');
INSERT INTO "cooking_steps" VALUES(53,2,2,'Mix mayonnaise, creme fraiche, curry powder, salt and pepper for a dressing. Rinse and finely snip the chives.');
INSERT INTO "cooking_steps" VALUES(53,3,0,'Carefully fold cooled chopped eggs and chives into the dressing. Mix only until combined so small pieces of egg remain.');
INSERT INTO "cooking_steps" VALUES(53,4,0,'Rinse and cut the tomatoes. Serve egg salad on rye bread with tomato on the side. Refrigerate if serving later.');
INSERT INTO "cooking_steps" VALUES(54,1,1,'Cook the pasta according to the packet, drain and briefly rinse with cold water. Drain thoroughly in a colander. Use immediately for the salad or cool quickly.');
INSERT INTO "cooking_steps" VALUES(54,2,2,'Cut the meat into small even cubes on a separate board, then wash hands and utensils. Heat the oil and fry the meat for 8–12 minutes with half the salt. Check for at least 75 °C in the centre. Spread on a clean plate to cool slightly.');
INSERT INTO "cooking_steps" VALUES(54,3,0,'Rinse and dice tomato and cucumber. Drain the sweetcorn. Mix yoghurt, mayonnaise, the remaining salt and pepper into a dressing.');
INSERT INTO "cooking_steps" VALUES(54,4,0,'Fold pasta, vegetables and cooked meat into the dressing. Use a large bowl so the ingredients can be mixed without crushing.');
INSERT INTO "cooking_steps" VALUES(54,5,0,'Serve immediately or promptly refrigerate in a closed container. Do not leave the dish standing at room temperature for a long time.');
INSERT INTO "cooking_steps" VALUES(55,1,1,'Put couscous in a heatproof bowl. Add the amount of boiling water on the packet, cover with a lid or plate and leave for 5–10 minutes. Fluff with a fork; the grains must be tender.');
INSERT INTO "cooking_steps" VALUES(55,2,5,'Peel and finely chop the red onion. Rinse cucumber, tomato and parsley. Finely dice cucumber and tomato and chop the parsley. Rinse and drain the cooked chickpeas.');
INSERT INTO "cooking_steps" VALUES(55,3,0,'Squeeze the lemon and whisk the juice with olive oil, salt and pepper. Fold the dressing into the couscous with chickpeas and chopped vegetables.');
INSERT INTO "cooking_steps" VALUES(55,4,0,'Fold in parsley and serve warm or chilled. For storage, spread in a shallow container and refrigerate promptly.');
INSERT INTO "cooking_steps" VALUES(56,1,1,'Cook the bulgur according to the packet. Drain any excess water and fluff with a fork. Spread on a large dish to release a little steam.');
INSERT INTO "cooking_steps" VALUES(56,2,6,'Peel and chop the red onion. Rinse vegetables and parsley. Remove pepper seeds and finely dice tomato, cucumber and pepper. Chop the parsley.');
INSERT INTO "cooking_steps" VALUES(56,3,0,'Squeeze the lemon. Whisk the juice with oil, salt and pepper. Fold the dressing into the warm bulgur with prepared vegetables and parsley.');
INSERT INTO "cooking_steps" VALUES(56,4,2,'Crumble feta on top and fold once gently. Serve warm or cold and refrigerate leftovers promptly.');
INSERT INTO "cooking_steps" VALUES(57,1,3,'Peel and very thinly slice the red onion. Rinse tomato and cucumber and cut into bite-size pieces. Drain the olives.');
INSERT INTO "cooking_steps" VALUES(57,2,0,'Squeeze the lemon and mix its juice with olive oil, oregano, salt and pepper for a dressing.');
INSERT INTO "cooking_steps" VALUES(57,3,0,'Mix vegetables and olives in a bowl. Add dressing and toss gently. Crumble or dice the feta and arrange over the salad.');
INSERT INTO "cooking_steps" VALUES(57,4,0,'Slice the bread and serve alongside. The salad is best freshly made; refrigerate until serving.');
INSERT INTO "cooking_steps" VALUES(58,1,3,'Peel and chop the onion. Peel and finely dice the carrots. Rinse lentils in a fine sieve.');
INSERT INTO "cooking_steps" VALUES(58,2,0,'Heat the oil in a saucepan and cook the vegetables for 5 minutes. Stir in cumin for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(58,3,1,'Add lentils, tomatoes, stock powder and about 250 ml water per serving. Simmer for 20–25 minutes until the lentils are completely soft. Stir often and add water if the soup becomes too thick.');
INSERT INTO "cooking_steps" VALUES(58,4,0,'Squeeze in lemon juice and stir in salt. Roughly mash the soup or blend carefully if a smooth texture is wanted. It must be hot throughout.');
INSERT INTO "cooking_steps" VALUES(58,5,0,'Serve with bread. If using a hand blender, submerge the blade before starting to prevent splashes of hot liquid.');
INSERT INTO "cooking_steps" VALUES(59,1,6,'Peel and chop the onion. Peel potatoes, carrots and celeriac and cut into small even cubes. Split leeks lengthways, rinse between the layers and cut into rings. Rinse pearl barley in a sieve.');
INSERT INTO "cooking_steps" VALUES(59,2,0,'Heat the oil in a large saucepan. Stir and cook onion, leek and root vegetables for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(59,3,1,'Add pearl barley, stock powder, thyme and about 350 ml water per serving. Bring to a gentle simmer, partly cover and cook for 25–35 minutes or the time on the barley packet.');
INSERT INTO "cooking_steps" VALUES(59,4,0,'Check the grains are tender with a little bite and the potatoes soft. Stir in salt and pepper, add water to reach a soup consistency and heat through.');
INSERT INTO "cooking_steps" VALUES(59,5,0,'Divide between deep plates. Stir the pan before each serving so everybody receives both grains and vegetables.');
INSERT INTO "cooking_steps" VALUES(60,1,3,'Peel and chop the onion. Peel carrots, potatoes and ginger. Finely dice the root vegetables and finely chop the ginger.');
INSERT INTO "cooking_steps" VALUES(60,2,0,'Heat the oil in a large saucepan. Cook onion and ginger for 3 minutes. Add carrot and potato and cook for another 3 minutes.');
INSERT INTO "cooking_steps" VALUES(60,3,0,'Add stock powder and about 200 ml water per serving. Cover and simmer for 20–25 minutes until all vegetables are completely tender.');
INSERT INTO "cooking_steps" VALUES(60,4,0,'Carefully mash or blend the soup in the pan. Stir in coconut milk and salt and heat gently for 3–4 minutes. Adjust thickness with water.');
INSERT INTO "cooking_steps" VALUES(60,5,0,'Serve the hot soup with bread. Keep a hand blender blade below the surface to avoid splashes of hot soup.');
INSERT INTO "cooking_steps" VALUES(61,1,3,'Peel and chop the onion. Peel and finely dice the potatoes. Rinse the broccoli, cut small florets and peel the thick stalk before dicing it.');
INSERT INTO "cooking_steps" VALUES(61,2,0,'Heat the oil in a saucepan and cook onion and potatoes for 5 minutes. Add stock powder and about 250 ml water per serving. Simmer for 12 minutes.');
INSERT INTO "cooking_steps" VALUES(61,3,1,'Add the broccoli, cover and cook for another 8–10 minutes. Both stalk and potatoes must be completely tender when pierced with a knife.');
INSERT INTO "cooking_steps" VALUES(61,4,0,'Carefully mash or blend the soup. Stir in cooking cream, salt and pepper and heat for 3 minutes. Add a little water if too thick.');
INSERT INTO "cooking_steps" VALUES(61,5,0,'Serve with bread. Keep a hand blender blade below the surface before switching on to avoid hot splashes.');
INSERT INTO "cooking_steps" VALUES(62,1,7,'Peel and chop onion and garlic. Peel the carrots; rinse celery and courgette. Finely dice all vegetables. Rinse and drain the cooked beans.');
INSERT INTO "cooking_steps" VALUES(62,2,0,'Heat the oil in a large saucepan. Cook onion, carrot and celery for 6 minutes. Stir in garlic for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(62,3,0,'Add courgette, tomatoes, stock powder, oregano and about 300 ml water per serving. Simmer for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(62,4,1,'Add pasta and cook for the packet time, stirring regularly. Add cooked beans for the last 5 minutes. Pasta and vegetables must be tender and beans hot throughout.');
INSERT INTO "cooking_steps" VALUES(62,5,0,'Stir in salt and pepper. Add water to reach a soup consistency and serve hot. Only use already cooked beans in this recipe.');
INSERT INTO "cooking_steps" VALUES(63,1,1,'Heat a conventional oven to 190 °C. Peel the potatoes and slice very thinly, about 2–3 mm thick. Oil a wide ovenproof dish.');
INSERT INTO "cooking_steps" VALUES(63,2,0,'Peel and finely chop the garlic. Dice the ham. Layer potato slices, ham and garlic in the dish.');
INSERT INTO "cooking_steps" VALUES(63,3,4,'Mix milk, cooking cream, nutmeg, salt and pepper. Pour evenly over the potatoes and press gently with a spoon to moisten the layers.');
INSERT INTO "cooking_steps" VALUES(63,4,0,'Cover loosely with foil and bake for 35 minutes. Remove foil, sprinkle with cheese and bake for another 20–25 minutes.');
INSERT INTO "cooking_steps" VALUES(63,5,0,'Check the centre with a knife: all potato layers must be tender and the dish hot and golden. Allow longer for thick slices. Rest for 5 minutes before serving.');
INSERT INTO "cooking_steps" VALUES(64,1,4,'Heat a conventional oven to 190 °C. Peel and chop the onion. Clean and slice the mushrooms. Rinse, deseed and dice the pepper.');
INSERT INTO "cooking_steps" VALUES(64,2,1,'Season the chops with half the salt and the pepper. Heat half the oil in a frying pan and brown for about 2 minutes per side. Put in an ovenproof dish.');
INSERT INTO "cooking_steps" VALUES(64,3,0,'Cook onion, mushrooms and pepper in the remaining oil for 6–8 minutes. Stir in paprika, tomatoes, cooking cream and the remaining salt. Bring to a simmer for 2 minutes.');
INSERT INTO "cooking_steps" VALUES(64,4,1,'Pour the hot sauce and vegetables over the meat. Bake for 20–25 minutes until the chops are cooked throughout. Check a thick piece; at least 75 °C is a simple check for fully cooked meat. Allow longer for thick chops.');
INSERT INTO "cooking_steps" VALUES(64,5,7,'Cook the rice according to the packet while the dish is in the oven. Serve with hot sauce, vegetables and cooked meat.');
INSERT INTO "cooking_steps" VALUES(65,1,3,'Peel and dice the potatoes. Boil in unsalted water for 15–20 minutes until completely tender. Drain and leave to steam dry for 1 minute.');
INSERT INTO "cooking_steps" VALUES(65,2,2,'Peel and chop the onions. Heat the oil in a saucepan and cook for 5 minutes until soft.');
INSERT INTO "cooking_steps" VALUES(65,3,1,'Add minced meat, break it up thoroughly with a spoon and cook for 6–8 minutes until fully cooked and at least 75 °C. Sprinkle with flour and stir for 1 minute.');
INSERT INTO "cooking_steps" VALUES(65,4,0,'Gradually stir in stock powder and about 150 ml water per serving. Add half the salt and the pepper. Simmer for 10 minutes until the gravy is smooth.');
INSERT INTO "cooking_steps" VALUES(65,5,6,'Heat the milk. Mash the potatoes with butter, hot milk and the remaining salt. Serve the soft mash with hot meat gravy.');
INSERT INTO "cooking_steps" VALUES(66,1,3,'Peel the onions and cut into strips. Clean and quarter the mushrooms. Pat the meat dry with kitchen paper.');
INSERT INTO "cooking_steps" VALUES(66,2,1,'Heat half the oil in a saucepan over medium-high heat. Brown small batches of meat for 3–4 minutes per batch. Transfer to a clean plate to avoid overcrowding the saucepan.');
INSERT INTO "cooking_steps" VALUES(66,3,0,'Heat the remaining oil and cook onion and mushrooms for 6–8 minutes. Stir in paprika and tomato puree for 1 minute. Return the meat and add stock powder and about 100 ml water per serving.');
INSERT INTO "cooking_steps" VALUES(66,4,1,'Cover and simmer for about 60–90 minutes until the meat is tender. Test a piece with a fork. Cooking time depends on the cut; tough stewing beef needs longer. Stir occasionally and add water if the saucepan becomes dry.');
INSERT INTO "cooking_steps" VALUES(66,5,0,'Stir in cooking cream, salt and pepper and heat gently for 5 minutes. Cook the rice separately according to the packet and serve with hot stroganoff.');
INSERT INTO "cooking_steps" VALUES(67,1,5,'Heat a conventional oven to 190 °C. Peel and chop onion and garlic. Heat the oil in a saucepan and cook the onion for 5 minutes. Add garlic for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(67,2,0,'Add tomato passata, basil, salt and pepper. Simmer for 5 minutes and pour into an ovenproof dish.');
INSERT INTO "cooking_steps" VALUES(67,3,1,'Split large pieces of meat lengthways so they have an even thickness. Put them in the sauce and wash hands and utensils after raw meat. Top with mozzarella. Bake for about 25–30 minutes; check for at least 75 °C in the thickest part.');
INSERT INTO "cooking_steps" VALUES(67,4,4,'Cook the pasta according to the packet while the dish is baking. Drain and keep warm.');
INSERT INTO "cooking_steps" VALUES(67,5,0,'Serve the fully cooked meat with hot tomato sauce and pasta. Extend the baking time for very thick meat rather than relying only on the clock.');
INSERT INTO "cooking_steps" VALUES(68,1,2,'Heat a conventional oven to 200 °C. Scrub potatoes and cut into wedges. Peel carrots and cut into thick sticks. Toss the vegetables with half the oil and half the salt.');
INSERT INTO "cooking_steps" VALUES(68,2,1,'Put the chicken legs in a large ovenproof dish. Rub with the remaining oil, paprika, rosemary, pepper and remaining salt. Wash hands and all utensils that touched raw meat.');
INSERT INTO "cooking_steps" VALUES(68,3,0,'Arrange vegetables around the meat in a single layer. Use several dishes for more servings, leaving space between pieces.');
INSERT INTO "cooking_steps" VALUES(68,4,1,'Bake for about 45–55 minutes and turn the vegetables after 25 minutes. Check for at least 75 °C in the thickest part near the bone without touching the bone with the thermometer. The meat must be fully cooked and potatoes tender.');
INSERT INTO "cooking_steps" VALUES(68,5,0,'Rest the meat for 5 minutes before serving. If the potatoes need more colour, remove the meat while giving the vegetables extra time.');
INSERT INTO "cooking_steps" VALUES(69,1,2,'Heat a conventional oven to 190 °C. Split leeks lengthways, rinse thoroughly between the layers and cut into rings. Melt the butter in a saucepan and cook the leeks over medium heat for 6–8 minutes until soft.');
INSERT INTO "cooking_steps" VALUES(69,2,0,'Stir cooking cream, milk, pepper and half the salt into the vegetables. Simmer for 3 minutes and pour into an ovenproof dish.');
INSERT INTO "cooking_steps" VALUES(69,3,1,'Check the fish for bones. Put it on the leek sauce, add the remaining salt and arrange lemon slices on top. Bake for about 15–20 minutes until hot throughout and easy to separate into flakes.');
INSERT INTO "cooking_steps" VALUES(69,4,3,'Peel the potatoes and boil in water for 15–20 minutes until a knife slides through easily. Drain.');
INSERT INTO "cooking_steps" VALUES(69,5,0,'Serve hot fish and sauce with potatoes. Check the thickest part of the fish and give it extra time if not yet cooked.');
INSERT INTO "cooking_steps" VALUES(70,1,0,'Peel potatoes and carrots. Thinly slice the carrots. Rinse and chop the parsley. Boil potatoes in water for 15–20 minutes until tender, then drain.');
INSERT INTO "cooking_steps" VALUES(70,2,1,'Cut the meat into small even cubes on a separate board, then wash hands and utensils. Bring about 150 ml water per serving to the boil with stock powder in another saucepan. Add meat and carrots and simmer for 12–15 minutes.');
INSERT INTO "cooking_steps" VALUES(70,3,1,'Check for at least 75 °C in one of the largest pieces of meat. Lift out cooked meat and vegetables with a slotted spoon and reserve the cooking water.');
INSERT INTO "cooking_steps" VALUES(70,4,6,'Melt the butter in a saucepan and stir in flour. Gradually whisk in milk and reserved cooking water until lightly creamy. Simmer for 5 minutes while stirring.');
INSERT INTO "cooking_steps" VALUES(70,5,0,'Fold meat, carrots and peas into the sauce. Heat for 5 minutes until the peas are hot. Add parsley, salt and pepper and serve with potatoes.');
INSERT INTO "cooking_steps" VALUES(71,1,1,'Peel the potatoes and cut into small even cubes. Boil in water for 8–10 minutes until almost tender. Drain and leave on a dish to steam dry for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(71,2,3,'Peel and chop the onions. Dice the ham. Heat about two-thirds of the oil in a large frying pan and cook potatoes for 10–15 minutes until tender and golden.');
INSERT INTO "cooking_steps" VALUES(71,3,0,'Add onion and ham and cook for another 6–8 minutes. Stir carefully to avoid mashing the potatoes. Add salt and pepper.');
INSERT INTO "cooking_steps" VALUES(71,4,4,'Heat the remaining oil in another pan over medium heat. Crack in the eggs one at a time and fry for about 4–5 minutes until the whites are completely firm. For firm yolks, cook longer under a lid.');
INSERT INTO "cooking_steps" VALUES(71,5,0,'Serve the hot hash with fried eggs, pickled beetroot and ketchup. For more servings, fry the potatoes in batches.');
INSERT INTO "cooking_steps" VALUES(72,1,3,'Peel and finely chop onion and garlic. Clean and slice the mushrooms. Grate the Parmesan. Bring about 300 ml water per serving to the boil with stock powder and keep warm over low heat.');
INSERT INTO "cooking_steps" VALUES(72,2,2,'Heat half the oil in a frying pan and cook mushrooms for 7–9 minutes until their liquid has evaporated and they are golden. Remove from the heat.');
INSERT INTO "cooking_steps" VALUES(72,3,1,'Heat the remaining oil in a wide saucepan. Cook onion for 4 minutes, garlic for 30 seconds, then stir in risotto rice for 1 minute. The rice should turn glossy, not brown.');
INSERT INTO "cooking_steps" VALUES(72,4,1,'Add hot stock one small ladle at a time, stirring often. Add more when the liquid is almost absorbed. Continue for about 18–25 minutes, following the rice packet, until tender with a little bite. Add extra hot water if needed.');
INSERT INTO "cooking_steps" VALUES(72,5,0,'Fold mushrooms, butter, Parmesan, salt and pepper into the cooked rice. Rest for 2 minutes. The risotto should be soft and creamy and slowly spread on the plate; stir in hot water if too firm.');
INSERT INTO "cooking_steps" VALUES(73,1,4,'Peel and chop the onion. Clean and slice the mushrooms. Rinse pearl barley and fresh spinach; frozen spinach can be added later without thawing.');
INSERT INTO "cooking_steps" VALUES(73,2,0,'Heat the oil in a wide saucepan. Cook onion and mushrooms for 8 minutes until the mushroom liquid has evaporated.');
INSERT INTO "cooking_steps" VALUES(73,3,1,'Add pearl barley, stock powder and about 225 ml water per serving. Simmer for 25–35 minutes or the packet time. Stir often and add water if dry before the grains become tender.');
INSERT INTO "cooking_steps" VALUES(73,4,3,'Stir spinach into the almost-tender grains. Simmer for 5 minutes until completely thawed or wilted and hot throughout. The dish should be creamy rather than watery.');
INSERT INTO "cooking_steps" VALUES(73,5,0,'Grate Parmesan and stir in with salt and pepper. Serve hot in deep plates.');
INSERT INTO "cooking_steps" VALUES(74,1,3,'Peel and grate the onion. Peel potatoes and carrots and coarsely grate them. Squeeze liquid from the grated potatoes in a clean tea towel so the mixture is not watery.');
INSERT INTO "cooking_steps" VALUES(74,2,0,'Mix the grated vegetables with egg, oats, cheese, half the salt and pepper. Rest for 10 minutes so the oats absorb liquid.');
INSERT INTO "cooking_steps" VALUES(74,3,0,'Peel and chop garlic and mix with yoghurt and remaining salt. Rinse lettuce and tomato and cut for a simple side salad.');
INSERT INTO "cooking_steps" VALUES(74,4,0,'Heat the oil in a frying pan over medium heat. Shape small flat patties and fry for about 5–7 minutes per side. They must be golden and hot throughout, with potato pieces tender when tasted. Thick patties need longer.');
INSERT INTO "cooking_steps" VALUES(74,5,0,'Serve hot patties with yoghurt dip and salad. Keep the uncooked mixture refrigerated between batches.');
INSERT INTO "cooking_steps" VALUES(75,1,4,'Peel and chop onion and garlic. Rinse the cauliflower, remove leaves and cut into small florets. Rinse and drain the cooked chickpeas. Cook the rice according to the packet.');
INSERT INTO "cooking_steps" VALUES(75,2,0,'Heat the oil in a saucepan. Cook onion for 5 minutes, then stir in garlic and curry powder for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(75,3,1,'Add cauliflower, coconut milk and about 50 ml water per serving. Cover and simmer for 10–12 minutes until the florets are almost tender.');
INSERT INTO "cooking_steps" VALUES(75,4,0,'Add cooked chickpeas and salt and simmer for another 5–8 minutes. Cauliflower must be tender with a little bite and chickpeas hot. Add water if the sauce is too thick.');
INSERT INTO "cooking_steps" VALUES(75,5,0,'Serve the hot curry with rice. This recipe uses cooked chickpeas; raw dried chickpeas cannot be added directly.');
INSERT INTO "cooking_steps" VALUES(76,1,1,'Drain the tofu. Press between clean tea towels or kitchen paper for 5 minutes, then cut into even cubes. A drier surface browns more easily.');
INSERT INTO "cooking_steps" VALUES(76,2,0,'Rinse broccoli and cut into small florets. Peel carrots and cut into thin strips. Rinse and slice spring onions; peel and chop garlic.');
INSERT INTO "cooking_steps" VALUES(76,3,1,'Heat half the oil in a large frying pan. Fry tofu cubes for 8–10 minutes over medium-high heat, turning carefully until several sides are golden. Remove from the pan.');
INSERT INTO "cooking_steps" VALUES(76,4,2,'Cook noodles according to the packet and drain. Fry vegetables in the remaining oil for 5–6 minutes, adding garlic for the final minute.');
INSERT INTO "cooking_steps" VALUES(76,5,0,'Fold noodles, fried tofu and soy sauce into the tender vegetables. Heat for 2 minutes and sprinkle with sesame seeds to serve.');
INSERT INTO "cooking_steps" VALUES(77,1,1,'Heat a conventional oven to 200 °C. Rinse and halve aubergines lengthways. Score the flesh in a grid without cutting the skin. Brush with half the oil and half the salt. Bake cut-side up for 25 minutes.');
INSERT INTO "cooking_steps" VALUES(77,2,4,'Peel and chop the onion. Rinse and drain the cooked lentils. Heat the remaining oil in a saucepan and cook onion for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(77,3,0,'Add lentils, tomatoes, oregano, pepper and remaining salt. Simmer for 12–15 minutes until the filling is hot and thick.');
INSERT INTO "cooking_steps" VALUES(77,4,1,'Remove the partly baked aubergines. Press the softened flesh down slightly with a spoon and add the filling. Crumble feta on top and bake for another 12–15 minutes. The aubergine flesh must be completely soft.');
INSERT INTO "cooking_steps" VALUES(77,5,6,'Prepare couscous with the water quantity and standing time on the packet. Fluff with a fork and serve with the hot filled vegetables.');
INSERT INTO "cooking_steps" VALUES(78,1,1,'Heat a conventional oven to 190 °C. Rinse peppers, halve lengthways and remove seeds and stalks. Put the halves in an ovenproof dish. Cook rice according to the packet.');
INSERT INTO "cooking_steps" VALUES(78,2,4,'Peel and chop the onion. Heat the oil in a saucepan and cook onion for 5 minutes.');
INSERT INTO "cooking_steps" VALUES(78,3,2,'Add minced meat and break up the lumps with a spoon. Cook for 6–8 minutes until fully cooked and at least 75 °C. Stir in paprika, oregano, tomatoes, salt and pepper and simmer for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(78,4,0,'Fold cooked rice into the meat filling and divide between pepper halves. Sprinkle with cheese and add about 25 ml water per serving to the bottom of the dish.');
INSERT INTO "cooking_steps" VALUES(78,5,0,'Bake for 25–30 minutes until peppers are tender, cheese golden and filling hot throughout. Cover loosely with foil if the cheese colours too early.');
INSERT INTO "cooking_steps" VALUES(79,1,4,'Peel and chop onion and garlic. Rinse and deseed the pepper and cut into small cubes.');
INSERT INTO "cooking_steps" VALUES(79,2,0,'Heat the oil in a wide pan with a lid. Cook onion and pepper for 7–8 minutes until soft. Add garlic, paprika and cumin for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(79,3,0,'Add tomatoes, salt and pepper. Simmer uncovered for 12–15 minutes until the sauce is thick, stirring occasionally.');
INSERT INTO "cooking_steps" VALUES(79,4,1,'Make small hollows in the sauce with a spoon and crack an egg into each. Cover and simmer gently for about 7–10 minutes until whites are completely set. Allow extra time for firm yolks.');
INSERT INTO "cooking_steps" VALUES(79,5,0,'Serve straight from the pan with bread to scoop up the sauce. For more servings, use several pans so the eggs lie in one layer.');
INSERT INTO "cooking_steps" VALUES(80,1,1,'Peel the potatoes and cut into thin slices. Boil in water for 6–8 minutes until almost tender, then drain.');
INSERT INTO "cooking_steps" VALUES(80,2,2,'Peel and thinly slice the onions. Heat half the oil in a large frying pan and cook onion over medium heat for 8 minutes until soft. Fold in potato slices for 2 minutes.');
INSERT INTO "cooking_steps" VALUES(80,3,3,'Whisk eggs with salt and pepper in a large bowl. Fold in the slightly cooled potatoes and onions so all slices are coated.');
INSERT INTO "cooking_steps" VALUES(80,4,3,'Heat the remaining oil in a frying pan over low-to-medium heat. Add the mixture, spread potatoes evenly and cover. Let set for about 12–18 minutes until the centre is firm without liquid egg. Make several smaller omelettes for more servings.');
INSERT INTO "cooking_steps" VALUES(80,5,0,'Rinse and slice the tomatoes. Rest the omelette for 3 minutes, cut into pieces and serve with tomatoes.');
INSERT INTO "cooking_steps" VALUES(81,1,4,'Peel and chop the onion. Remove outer cabbage leaves and the tough core, then finely shred the cabbage. Peel potatoes and carrots and finely dice them.');
INSERT INTO "cooking_steps" VALUES(81,2,1,'Heat the oil in a large saucepan. Cook onion for 4 minutes, add minced meat and break up the lumps. Cook for 6–8 minutes until fully cooked and at least 75 °C.');
INSERT INTO "cooking_steps" VALUES(81,3,0,'Stir in paprika. Gradually add cabbage, potatoes and carrots, folding until the cabbage wilts.');
INSERT INTO "cooking_steps" VALUES(81,4,0,'Add stock powder, salt, pepper and about 150 ml water per serving. Cover and simmer for 20–25 minutes. Stir along the bottom every few minutes.');
INSERT INTO "cooking_steps" VALUES(81,5,0,'Check that potatoes and cabbage are completely tender. The dish should be moist rather than a thin soup; add water if needed. Serve piping hot.');
INSERT INTO "cooking_steps" VALUES(82,1,2,'Peel and grate the onion. Mix minced meat with onion, egg, oats, about one-sixth of the milk, half the salt and pepper. Refrigerate for 10 minutes. Reserve the remaining milk for the cabbage sauce.');
INSERT INTO "cooking_steps" VALUES(82,2,7,'Peel the potatoes and boil in water for 15–20 minutes until tender. Drain. Remove the cabbage core and cut the leaves into strips.');
INSERT INTO "cooking_steps" VALUES(82,3,6,'Boil cabbage in a separate saucepan of water for 8–12 minutes until tender. Drain through a colander and leave to drain thoroughly.');
INSERT INTO "cooking_steps" VALUES(82,4,1,'Heat the oil in a frying pan. Shape small meatballs and fry over medium heat for about 5–7 minutes per side. Check for at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(82,5,5,'Melt the butter in a large saucepan. Stir in flour, then gradually whisk in reserved milk. Simmer for 5 minutes while stirring. Fold in drained cabbage and add nutmeg and remaining salt.');
INSERT INTO "cooking_steps" VALUES(82,6,0,'Heat the creamed cabbage for 3 minutes without burning the bottom. Serve with fully cooked meatballs and potatoes.');
INSERT INTO "cooking_steps" VALUES(83,1,4,'Peel and chop the onion. Peel and finely dice potatoes and carrots. Thoroughly rinse fresh kale, remove coarse stalks and finely chop the leaves. Frozen chopped kale can be used without thawing.');
INSERT INTO "cooking_steps" VALUES(83,2,0,'Heat the oil in a large saucepan and cook onion for 4 minutes. Add potatoes, carrots, stock powder and about 300 ml water per serving.');
INSERT INTO "cooking_steps" VALUES(83,3,0,'Cover and simmer the vegetables for 15 minutes. Mash some potato against the side of the pan with a spoon to thicken the soup.');
INSERT INTO "cooking_steps" VALUES(83,4,1,'Add kale and cook for another 8–10 minutes until tender and hot throughout. Stir in cooking cream, salt and pepper and heat for 3 minutes.');
INSERT INTO "cooking_steps" VALUES(83,5,0,'Check all vegetables are tender. Serve hot with bread and add hot water if the soup is too thick.');
INSERT INTO "cooking_steps" VALUES(84,1,5,'Peel and chop the onion. Peel and finely dice carrots and celeriac. Split leeks lengthways, rinse between the layers and slice into rings. Rinse split peas thoroughly.');
INSERT INTO "cooking_steps" VALUES(84,2,1,'Put split peas, stock powder, thyme, bay leaves and about 400 ml water per serving in a large saucepan. Bring to the boil, reduce the heat and simmer for 25 minutes. Skim off foam if necessary and stir the bottom often.');
INSERT INTO "cooking_steps" VALUES(84,3,0,'Add the prepared vegetables. Simmer for another 35–45 minutes, giving the peas at least 60 minutes in total. They should break down and the vegetables be tender. Add water if the soup becomes too thick.');
INSERT INTO "cooking_steps" VALUES(84,4,6,'Put sausages in another saucepan of water and heat slowly to just below boiling. Keep hot for 8–10 minutes or the packet time, until hot throughout.');
INSERT INTO "cooking_steps" VALUES(84,5,0,'Remove bay leaves from the soup. Add salt and pepper and serve with hot sausages and mustard. Split peas are not raw kidney beans; always use the specified ingredient and follow its packet.');
INSERT INTO "cooking_steps" VALUES(85,1,6,'Peel and chop the onion. Peel and finely dice carrots and celeriac. Rinse leeks thoroughly between the layers and cut into rings. Rinse the pearl barley.');
INSERT INTO "cooking_steps" VALUES(85,2,0,'Heat the oil in a large saucepan. Cook vegetables for 5 minutes. Add barley, stock powder and about 350 ml water per serving and simmer for 15 minutes.');
INSERT INTO "cooking_steps" VALUES(85,3,1,'Cut the meat into small even cubes on a separate board, then wash hands and utensils. Add the meat to the simmering soup and cook for another 15–20 minutes. Check for at least 75 °C in the thickest piece.');
INSERT INTO "cooking_steps" VALUES(85,4,0,'Check the barley is tender with a little bite and vegetables soft. Add salt and pepper. Rinse and chop parsley and stir it in.');
INSERT INTO "cooking_steps" VALUES(85,5,0,'Serve the soup hot. Add water if the grains have absorbed so much liquid that the dish resembles porridge.');
INSERT INTO "cooking_steps" VALUES(86,1,2,'Cut the meat into small even cubes on a separate board, then wash hands and utensils. Bring about 150 ml water per serving to the boil with stock powder. Add meat and simmer gently for 12–15 minutes until fully cooked and at least 75 °C. Lift out with a slotted spoon and reserve the cooking water.');
INSERT INTO "cooking_steps" VALUES(86,2,3,'Drain the asparagus in a colander. Cut large pieces into smaller bites without crushing them.');
INSERT INTO "cooking_steps" VALUES(86,3,4,'Melt the butter in a saucepan and stir in flour. Gradually whisk in milk. Add reserved cooking water until the sauce is thick but stirrable. Simmer for 5 minutes while stirring.');
INSERT INTO "cooking_steps" VALUES(86,4,0,'Carefully fold cooked meat and asparagus into the sauce and add salt and pepper. Heat gently for 3–5 minutes until everything is hot.');
INSERT INTO "cooking_steps" VALUES(86,5,1,'Warm the pastry cases according to the packet, typically for a few minutes in the oven. Put on plates and fill with the hot mixture just before serving so the cases stay crisp.');
INSERT INTO "cooking_steps" VALUES(87,1,1,'Scrub or peel potatoes and boil in water for 15–20 minutes until just tender. Drain, cut into smaller pieces and spread on a clean dish to cool quickly.');
INSERT INTO "cooking_steps" VALUES(87,2,3,'Peel and very finely chop the red onion. Rinse and snip chives. Mix creme fraiche, mayonnaise, mustard, salt and pepper, then fold in chopped herbs and onion.');
INSERT INTO "cooking_steps" VALUES(87,3,0,'Carefully fold the cooled potatoes into the dressing. Refrigerate the salad while cooking the sausages.');
INSERT INTO "cooking_steps" VALUES(87,4,2,'Heat the oil in a frying pan over medium heat. Fry sausages for 8–10 minutes, turning, or follow the packet if longer. They must be hot throughout.');
INSERT INTO "cooking_steps" VALUES(87,5,0,'Serve hot sausages with cold potato salad. Refrigerate leftovers promptly; do not leave the dressing standing warm for a long time.');
INSERT INTO "cooking_steps" VALUES(88,1,2,'Peel the potatoes and boil in water with half the salt for 15–20 minutes until tender. Drain.');
INSERT INTO "cooking_steps" VALUES(88,2,1,'Check fillets for bones and pat dry with kitchen paper. Mix flour, remaining salt and pepper on a plate and lightly coat the fillets.');
INSERT INTO "cooking_steps" VALUES(88,3,1,'Melt about two-thirds of the butter in a frying pan over medium heat. Add fish when the butter foams gently. Fry for about 2–4 minutes per side, depending on thickness, until hot throughout, lightly golden and flaky. Turn carefully with a wide spatula.');
INSERT INTO "cooking_steps" VALUES(88,4,0,'Rinse and chop parsley and toss with potatoes and remaining butter. Cut lemon into wedges.');
INSERT INTO "cooking_steps" VALUES(88,5,0,'Serve fish immediately with parsley potatoes and lemon. Fry in batches if the fillets would otherwise overlap.');
INSERT INTO "cooking_steps" VALUES(89,1,3,'Peel and finely grate the onion. Drain tuna thoroughly and flake with a fork. Mix with onion, egg, breadcrumbs, half the salt and pepper into a firm mixture. Refrigerate for 10 minutes.');
INSERT INTO "cooking_steps" VALUES(89,2,5,'Cook bulgur according to the packet and leave covered when tender. Rinse and grate cucumber and squeeze out some liquid.');
INSERT INTO "cooking_steps" VALUES(89,3,0,'Mix cucumber with yoghurt, lemon juice and remaining salt and refrigerate.');
INSERT INTO "cooking_steps" VALUES(89,4,0,'Heat the oil in a frying pan over medium heat. Shape small flat tuna patties and fry for about 4–5 minutes per side. They must be golden, firm and hot throughout, with the egg completely cooked.');
INSERT INTO "cooking_steps" VALUES(89,5,0,'Serve hot patties with bulgur and cold cucumber yoghurt. If the mixture is soft, make small flat patties and turn carefully.');
INSERT INTO "cooking_steps" VALUES(90,1,3,'Peel the potatoes and boil in water with half the salt for 15–20 minutes until a knife slides through easily. Drain.');
INSERT INTO "cooking_steps" VALUES(90,2,1,'Cook fish fingers from frozen using the oven temperature and time on the packet, typically about 15–20 minutes. Arrange in one layer and turn if instructed. The coating must be crisp and the fish hot in the centre.');
INSERT INTO "cooking_steps" VALUES(90,3,2,'Boil peas in a little water for 4–5 minutes until hot throughout. Reserve a little cooking water and drain the rest.');
INSERT INTO "cooking_steps" VALUES(90,4,0,'Roughly mash peas with a potato masher. Stir in butter, lemon juice, remaining salt and pepper. Add reserved cooking water if the mash is very firm.');
INSERT INTO "cooking_steps" VALUES(90,5,0,'Serve hot fish with green pea mash and potatoes. Plate immediately so the coating stays crisp.');
INSERT INTO "cooking_steps" VALUES(91,1,6,'Peel and chop onion and garlic. Peel carrots and rinse celery. Finely dice the vegetables. Rinse lentils in a fine sieve.');
INSERT INTO "cooking_steps" VALUES(91,2,0,'Heat the oil in a saucepan. Cook onion, carrot and celery for 6 minutes. Stir in garlic and tomato puree for 1 minute.');
INSERT INTO "cooking_steps" VALUES(91,3,2,'Add lentils, tomatoes, oregano, salt, pepper and about 100 ml water per serving. Simmer for 25–30 minutes until the lentils are completely tender. Stir the bottom often and add water if needed.');
INSERT INTO "cooking_steps" VALUES(91,4,1,'Cook spaghetti for the packet time in a large saucepan of water until tender with a little bite. Drain through a colander.');
INSERT INTO "cooking_steps" VALUES(91,5,0,'Fold spaghetti into the hot lentil sauce or spoon the sauce on top. The lentils must not have a hard centre when served.');
INSERT INTO "cooking_steps" VALUES(92,1,0,'Heat a conventional oven to 210 °C. Peel carrots and cut into sticks. Rinse cauliflower and cut small florets. Toss on a baking tray with half the oil and half the salt.');
INSERT INTO "cooking_steps" VALUES(92,2,0,'Roast for 25–30 minutes, turning after 15 minutes, until tender with golden edges.');
INSERT INTO "cooking_steps" VALUES(92,3,1,'Rinse and drain cooked chickpeas. Peel garlic and squeeze lemon juice. Put chickpeas, tahini, lemon juice, garlic, cumin, remaining oil and remaining salt in a bowl or blender.');
INSERT INTO "cooking_steps" VALUES(92,4,1,'Blend or mash thoroughly into a creamy dip. Gradually add cold water, starting with about one tablespoon per serving, until soft. Never use raw dried chickpeas directly for hummus.');
INSERT INTO "cooking_steps" VALUES(92,5,8,'Warm the pitta bread according to the packet and cut into triangles. Serve with hummus and hot roasted vegetables.');
INSERT INTO "cooking_steps" VALUES(93,1,5,'Peel and chop the onion. Peel sweet potatoes and cut into small cubes about 2 cm wide. Rinse and drain cooked chickpeas; rinse fresh spinach.');
INSERT INTO "cooking_steps" VALUES(93,2,0,'Heat the oil in a saucepan. Cook onion for 5 minutes and stir in cumin for 30 seconds.');
INSERT INTO "cooking_steps" VALUES(93,3,1,'Add sweet potato, chopped tomatoes, stock powder and about 150 ml water per serving. Cover and simmer for 15–20 minutes until potato pieces are almost tender.');
INSERT INTO "cooking_steps" VALUES(93,4,6,'Mix peanut butter with some hot liquid in a bowl until smooth. Return it to the saucepan and add cooked chickpeas and salt. Simmer for 5 minutes, stirring.');
INSERT INTO "cooking_steps" VALUES(93,5,4,'Stir in spinach and heat for another 3–5 minutes until wilted and hot throughout. Check sweet potatoes are tender. Serve in deep plates and add water if the sauce is too thick.');
INSERT INTO "cooking_steps" VALUES(94,1,2,'Cook rice in a separate saucepan according to the packet. Rinse and thinly slice cucumber. Squeeze the lime juice.');
INSERT INTO "cooking_steps" VALUES(94,2,1,'Cut the meat into thin even strips on a separate board, then wash hands and utensils. Heat the oil in a large frying pan and cook the meat for 8–12 minutes. Turn regularly; it must be fully cooked and at least 75 °C in the centre.');
INSERT INTO "cooking_steps" VALUES(94,3,3,'Put peanut butter, coconut milk, soy sauce and curry powder in a small saucepan. Heat gently, stirring for 5 minutes, until smooth and hot. Do not let it stick; add water if too thick.');
INSERT INTO "cooking_steps" VALUES(94,4,0,'Stir lime juice into the sauce. Divide rice and fully cooked meat between plates, spoon over hot sauce and serve cucumber on the side.');
INSERT INTO "cooking_steps" VALUES(95,1,2,'Cook rice according to the packet. Rinse broccoli and cut into small florets. Peel garlic and ginger and finely chop both.');
INSERT INTO "cooking_steps" VALUES(95,2,0,'Mix soy sauce, honey, mild vinegar, ginger and garlic in a bowl until the honey dissolves.');
INSERT INTO "cooking_steps" VALUES(95,3,1,'Cut the meat into even strips on a separate board, then wash hands and utensils. Heat the oil in a frying pan. Fry meat for 8–12 minutes, turning, until fully cooked and at least 75 °C.');
INSERT INTO "cooking_steps" VALUES(95,4,3,'Boil broccoli in water for 4–6 minutes until tender with a little bite, then drain.');
INSERT INTO "cooking_steps" VALUES(95,5,0,'Pour the mixed sauce over the cooked meat and bubble gently for 2–3 minutes, stirring. Fold in vegetables, sprinkle with sesame seeds and serve with rice. Lower the heat if the honey darkens.');
INSERT INTO "cooking_steps" VALUES(96,1,2,'Rinse and trim fresh beans; frozen beans can be used directly. Boil in water for 10–15 minutes, depending on size, until fully cooked and tender. Do not taste raw green beans. Drain.');
INSERT INTO "cooking_steps" VALUES(96,2,1,'Cook pasta in another saucepan of salted water according to the packet. Reserve a little cooking water before draining.');
INSERT INTO "cooking_steps" VALUES(96,3,0,'Rinse tomatoes and cut into small pieces. Grate Parmesan.');
INSERT INTO "cooking_steps" VALUES(96,4,4,'Toss hot pasta with pesto, cooked beans and a little reserved cooking water to spread the pesto. Fold in tomatoes last, sprinkle with Parmesan and serve immediately.');
INSERT INTO "cooking_steps" VALUES(97,1,4,'Peel and chop the onion. Rinse fresh spinach; frozen spinach can be added directly to the sauce later. Squeeze lemon juice. Cook pasta according to the packet and reserve some cooking water.');
INSERT INTO "cooking_steps" VALUES(97,2,2,'Check fish for bones and cut into bite-size cubes. Wash hands and utensils after raw fish. Heat the oil in a wide saucepan and cook onion for 5 minutes. Add fish cubes and turn gently for 2 minutes.');
INSERT INTO "cooking_steps" VALUES(97,3,2,'Add cooking cream and simmer gently for 6–10 minutes, depending on fish-piece size. The fish must be hot throughout and flake easily. Avoid vigorous stirring that breaks the pieces.');
INSERT INTO "cooking_steps" VALUES(97,4,3,'Stir spinach into the sauce and heat for 4–6 minutes until hot throughout and wilted. Add lemon juice, salt and pepper.');
INSERT INTO "cooking_steps" VALUES(97,5,0,'Carefully fold drained pasta into the hot sauce. Add reserved cooking water if too thick and serve immediately.');
INSERT INTO "cooking_steps" VALUES(98,1,4,'Peel and very finely chop the onion. Thoroughly rinse and drain cooked beans. Mash in a bowl with a fork, leaving some larger pieces if preferred.');
INSERT INTO "cooking_steps" VALUES(98,2,0,'Stir onion, oats, egg, paprika, cumin and salt into the beans. Refrigerate for 15 minutes so the oats absorb liquid.');
INSERT INTO "cooking_steps" VALUES(98,3,0,'Rinse lettuce and tomato, shred the lettuce and slice tomatoes. Split buns and briefly warm in the oven or toaster.');
INSERT INTO "cooking_steps" VALUES(98,4,0,'Heat the oil in a frying pan over medium heat. Shape flat bean patties and fry for about 5–6 minutes per side. Turn carefully; they must be firm and hot throughout, with the egg fully cooked.');
INSERT INTO "cooking_steps" VALUES(98,5,0,'Spread buns with mayonnaise and ketchup and fill with lettuce, a hot patty and tomato. Serve immediately. Only use cooked beans for the mixture.');
INSERT INTO "cooking_steps" VALUES(99,1,4,'Peel and chop onion and garlic. Rinse aubergine, courgette and pepper. Remove pepper seeds and cut all vegetables into even bite-size cubes.');
INSERT INTO "cooking_steps" VALUES(99,2,0,'Heat the oil in a large saucepan. Cook aubergine and onion for 6–8 minutes, stirring. Add courgette and pepper and cook for another 5 minutes.');
INSERT INTO "cooking_steps" VALUES(99,3,0,'Stir in garlic and thyme for 30 seconds. Add chopped tomatoes, salt and pepper. Half-cover and simmer for 20–25 minutes until all vegetables are tender. Stir regularly.');
INSERT INTO "cooking_steps" VALUES(99,4,7,'Prepare couscous with boiling water, using the packet water quantity and standing time. Fluff with a fork when tender.');
INSERT INTO "cooking_steps" VALUES(99,5,0,'Serve the hot vegetable stew over couscous. Add water while simmering if the pan becomes dry before the vegetables are tender.');
INSERT INTO "cooking_steps" VALUES(100,1,1,'Cook pasta according to the packet in salted water. Reserve about 75 ml cooking water per serving before draining.');
INSERT INTO "cooking_steps" VALUES(100,2,2,'Finely dice bacon and fry in a large pan over medium heat for 6–8 minutes until fully cooked and lightly crisp. Turn off the heat under the pan.');
INSERT INTO "cooking_steps" VALUES(100,3,3,'Grate Parmesan. Whisk eggs with cheese and pepper in a bowl until evenly mixed.');
INSERT INTO "cooking_steps" VALUES(100,4,0,'Toss hot pasta with the cooked meat. Add the egg mixture and some cooking water while stirring vigorously. Warm very gently, stirring continuously, until the sauce is creamy, hot throughout and set without raw egg. Never leave it unstirred over high heat.');
INSERT INTO "cooking_steps" VALUES(100,5,0,'Add more hot cooking water if the sauce is too firm and serve immediately. For more servings, use several pans so the mixture can be stirred effectively.');
