INSERT INTO "ingredients" VALUES(16,'turkey breast','kalkunbryst','g','Meat and fish');
INSERT INTO "ingredients" VALUES(17,'minced beef','hakket oksekød','g','Meat and fish');
INSERT INTO "ingredients" VALUES(18,'minced pork','hakket svinekød','g','Meat and fish');
INSERT INTO "ingredients" VALUES(19,'red lentils','røde linser','g','Pulses');
INSERT INTO "ingredients" VALUES(20,'cooked chickpeas','kogte kikærter','g','Pulses');
INSERT INTO "ingredients" VALUES(21,'cooked kidney beans','kogte kidneybønner','g','Pulses');
INSERT INTO "ingredients" VALUES(22,'eggs','æg','pcs','Dairy');
INSERT INTO "ingredients" VALUES(23,'milk','mælk','ml','Dairy');
INSERT INTO "ingredients" VALUES(24,'oat drink','havredrik','ml','Plant-based alternatives');
INSERT INTO "ingredients" VALUES(25,'cream','fløde','ml','Dairy');
INSERT INTO "ingredients" VALUES(26,'cooking cream','madlavningsfløde','ml','Dairy');
INSERT INTO "ingredients" VALUES(27,'butter','smør','g','Dairy');
INSERT INTO "ingredients" VALUES(28,'rapeseed oil','rapsolie','ml','Oils and sauces');
INSERT INTO "ingredients" VALUES(29,'olive oil','olivenolie','ml','Oils and sauces');
INSERT INTO "ingredients" VALUES(30,'wheat flour','hvedemel','g','Baking');
INSERT INTO "ingredients" VALUES(31,'oats','havregryn','g','Grains and bread');
INSERT INTO "ingredients" VALUES(32,'grated cheese','revet ost','g','Dairy');
INSERT INTO "ingredients" VALUES(33,'feta cheese','feta','g','Dairy');
INSERT INTO "ingredients" VALUES(34,'rye bread','rugbrød','g','Grains and bread');
INSERT INTO "ingredients" VALUES(35,'tortilla wraps','tortillapandekager','g','Grains and bread');
INSERT INTO "ingredients" VALUES(36,'tuna in water','tun i vand','g','Canned food');
INSERT INTO "ingredients" VALUES(37,'salmon','laks','g','Meat and fish');
INSERT INTO "ingredients" VALUES(38,'cod','torsk','g','Meat and fish');
INSERT INTO "ingredients" VALUES(39,'coconut milk','kokosmælk','ml','Canned food');
INSERT INTO "ingredients" VALUES(40,'curry powder','karry','g','Spices');
INSERT INTO "ingredients" VALUES(41,'paprika powder','paprika','g','Spices');
INSERT INTO "ingredients" VALUES(42,'salt','salt','g','Spices');
INSERT INTO "ingredients" VALUES(43,'black pepper','sort peber','g','Spices');
INSERT INTO "ingredients" VALUES(44,'soy sauce','sojasauce','ml','Oils and sauces');
INSERT INTO "ingredients" VALUES(45,'sweetcorn','majs','g','Canned food');
INSERT INTO "ingredients" VALUES(46,'green peas','grønne ærter','g','Vegetables');
INSERT INTO "ingredients" VALUES(47,'courgette','squash','g','Vegetables');
