INSERT INTO "recipes" VALUES(96,'Pesto pasta with green beans','pasta med pesto og groenne boenner | pesto pasta with green beans','Quick pasta tossed with pesto, green beans and tomatoes.',4,10,20,'Pasta med pesto og grønne bønner','Hurtig pasta vendt med pesto, grønne bønner og tomater.');
INSERT INTO "recipes" VALUES(97,'Salmon and spinach pasta','pasta med laks og spinat | salmon and spinach pasta','Pasta in a mild cream sauce with fully cooked fish and spinach.',4,15,25,'Pasta med laks og spinat','Pasta i mild flødesauce med gennemtilberedt fisk og spinat.');
INSERT INTO "recipes" VALUES(98,'Vegetarian bean burgers','vegetarisk boenneburger | vegetarian bean burgers','Pan-fried bean patties in buns with vegetables and dressing.',4,25,25,'Vegetarisk bønneburger','Pandestegte bønnebøffer i boller med grønt og dressing.');
INSERT INTO "recipes" VALUES(99,'Ratatouille with couscous','ratatouille med couscous | ratatouille with couscous','Gently simmered vegetables in tomato sauce with light couscous.',4,20,35,'Ratatouille med couscous','Langsomt simrede grøntsager i tomat med let couscous.');
INSERT INTO "recipes" VALUES(100,'Pasta carbonara','pasta carbonara | pasta carbonara','Pasta with bacon, eggs and Parmesan in a warm creamy sauce without cream.',4,15,20,'Pasta carbonara','Pasta med bacon, æg og parmesan i en varm, cremet sauce uden fløde.');
INSERT INTO "substitute_steps" VALUES(1,1,53,'Peel and finely chop the red onion. Peel the carrots and cut them into very small cubes. Open the tomatoes and measure all ingredients according to the list.');
INSERT INTO "substitute_steps" VALUES(1,2,18,'Heat the oil in a large saucepan over medium heat. Cook the vegetables for 5 minutes. Add minced pork, break up the lumps with a spoon and cook for 6–8 minutes until fully cooked and at least 75 °C in the centre.');
INSERT INTO "substitute_steps" VALUES(2,1,53,'Peel and chop the red onion. Peel and coarsely grate the carrots. Heat a conventional oven to 190 °C and choose an ovenproof dish deep enough for at least three layers.');
INSERT INTO "substitute_steps" VALUES(3,1,53,'Peel the red onion and finely grate it into a bowl. Peel potatoes and carrots. Coarsely grate the carrots for the raw salad and set aside.');
INSERT INTO "substitute_steps" VALUES(4,1,53,'Peel and finely grate the red onion. Mix the meat with red onion, egg, milk, half the flour, salt and pepper. Refrigerate for 10 minutes. Reserve the rest of the flour for the sauce.');
INSERT INTO "substitute_steps" VALUES(5,1,53,'Peel and chop the red onion. Peel the carrots and cut them into small even cubes. Cook the rice in a separate saucepan according to the packet.');
INSERT INTO "substitute_steps" VALUES(5,2,16,'Cut the turkey breast into even bite-size pieces on a separate board. Wash hands and utensils after handling raw turkey breast. Heat the oil and cook onion and carrot for 5 minutes. Add the turkey breast and brown the pieces on every side.');
INSERT INTO "substitute_steps" VALUES(5,4,16,'Check that the thickest piece of turkey breast is fully cooked and at least 75 °C in the centre. Cook longer if necessary. Add a little water if the sauce is very thick. Thickness matters more than the suggested time; cook longer when needed.');
INSERT INTO "substitute_steps" VALUES(6,3,16,'Cut the turkey breast into even strips on a separate board. Wash hands and utensils. Heat the oil in a frying pan over medium-high heat and cook the turkey breast for 8–12 minutes. Turn regularly; it must be fully cooked and at least 75 °C in the centre.');
INSERT INTO "substitute_steps" VALUES(7,1,53,'Peel and chop the red onion. Rinse the pepper, remove its stalk and seeds and dice the flesh. Rinse and drain the cooked beans. Cook the rice according to the packet.');
INSERT INTO "substitute_steps" VALUES(8,1,53,'Peel and chop the red onion. Rinse the pepper, remove the stalk and seeds and dice it. Rinse and drain both kinds of cooked beans and the sweetcorn.');
INSERT INTO "substitute_steps" VALUES(9,1,53,'Peel and chop the red onion. Clean the mushrooms with a brush or a quick rinse, then slice them. Cook the pasta according to the packet, reserving a little cooking water before draining.');
INSERT INTO "substitute_steps" VALUES(10,1,53,'Peel and finely chop the red onion. Peel and very finely chop the garlic. Grate the Parmesan if necessary.');
INSERT INTO "substitute_steps" VALUES(11,1,53,'Peel and very finely chop the red onion. Reserve half for the sauce. Mix the rest with minced meat, egg, breadcrumbs, half the salt and pepper. Shape small meatballs with damp hands.');
INSERT INTO "substitute_steps" VALUES(12,2,16,'Cut the turkey breast into thin even strips on a separate board. Wash hands and utensils. Heat half the oil in a large frying pan or wok and cook the turkey breast for 8–10 minutes until fully cooked and at least 75 °C. Transfer to a clean plate.');
INSERT INTO "substitute_steps" VALUES(13,2,16,'Cut the turkey breast into thin strips on a separate board, then wash hands and utensils. Heat the oil in a frying pan. Cook the turkey breast with paprika and the remaining salt for 8–12 minutes until fully cooked and at least 75 °C in the centre.');
INSERT INTO "substitute_steps" VALUES(14,1,53,'Peel and chop the red onion. Rinse lettuce and tomatoes, shred the lettuce and dice the tomatoes. Drain the sweetcorn and arrange the cold toppings in small bowls.');
INSERT INTO "substitute_steps" VALUES(15,1,53,'Peel and chop the red onion. Rinse and drain the cooked black beans. Cook the rice in a separate saucepan according to the packet.');
INSERT INTO "substitute_steps" VALUES(16,2,53,'Peel the red onion and cut it into thin rings. Rinse lettuce, tomato and cucumber. Shred the lettuce and slice tomato and cucumber.');
INSERT INTO "substitute_steps" VALUES(17,2,137,'Mix creme fraiche with garlic, lemon juice and salt. Add a little cold water if needed for a soft dressing. Refrigerate while preparing the hot components.');
INSERT INTO "substitute_steps" VALUES(18,2,38,'Check the cod for bones. Oil an ovenproof dish, add fish and season with half the salt and pepper. Slice lemon and arrange on top. Bake at 180 °C for about 12–18 minutes, depending on thickness, until hot throughout and flaky. Begin checking at 12 minutes.');
INSERT INTO "substitute_steps" VALUES(19,1,53,'Peel and finely grate the red onion. Peel potatoes and carrots. Coarsely grate the carrots and toss with lemon juice for the salad.');
INSERT INTO "substitute_steps" VALUES(20,1,53,'Peel and chop the red onion. Peel the potatoes and cut into small cubes. Split the leeks lengthways, rinse thoroughly between the layers and cut into thin rings.');
INSERT INTO "substitute_steps" VALUES(21,1,53,'Peel and chop the red onion. Peel the carrots and cut into small cubes. Heat the oil in a large saucepan and cook the vegetables for 5 minutes.');
INSERT INTO "substitute_steps" VALUES(22,2,24,'Whisk the eggs with unsweetened oat drink, salt and pepper in a bowl. Pour into the pan over low heat. Let the base set for about 5 minutes without stirring.');
INSERT INTO "substitute_steps" VALUES(23,2,24,'Whisk the eggs with unsweetened oat drink, salt and pepper. Pour over the spinach and sprinkle the cheese evenly on top.');
INSERT INTO "substitute_steps" VALUES(24,2,53,'Peel and chop the red onion. Slice the sausages. Heat the oil in a wide saucepan and cook the red onion for 4 minutes. Add sausages and cook for another 4 minutes.');
INSERT INTO "substitute_steps" VALUES(25,1,53,'Peel and chop the red onion. Clean and quarter the mushrooms. Rinse, deseed and dice the pepper. Cook the rice according to the packet.');
INSERT INTO "substitute_steps" VALUES(26,2,53,'Peel and thinly slice the red onions. Melt half the butter in a frying pan over medium heat. Cook the red onions slowly for 15–20 minutes, stirring often, until soft and golden. Remove from the pan.');
INSERT INTO "substitute_steps" VALUES(27,4,24,'Melt the butter in a saucepan. Stir in flour, then gradually whisk in unsweetened oat drink. Simmer for 4 minutes while stirring. Add the peas and heat for 5 minutes until hot throughout.');
INSERT INTO "substitute_steps" VALUES(29,1,53,'Peel and finely grate the red onion. Mix the minced meat with red onion, egg, oats, milk, half the salt and pepper. Refrigerate for 10 minutes.');
INSERT INTO "substitute_steps" VALUES(31,3,223,'Check the coalfish fillet for bones. Put on the vegetables, season with remaining salt and pepper and top with lemon slices. Bake at 200 °C for about 12–18 minutes, depending on thickness, until hot throughout and easy to flake.');
INSERT INTO "substitute_steps" VALUES(33,1,53,'Peel and chop the red onion. Peel garlic and ginger and finely chop both. Rinse the lentils thoroughly in a sieve. Cook the rice separately according to the packet.');
INSERT INTO "substitute_steps" VALUES(34,1,53,'Peel and chop red onion and garlic. Rinse and drain the cooked chickpeas. Rinse fresh spinach; frozen spinach can go straight into the pan later. Cook the rice according to the packet.');
INSERT INTO "substitute_steps" VALUES(35,1,53,'Heat a conventional oven to 190 °C. Peel and chop the red onion. Peel and grate the carrots; rinse and finely dice the courgette. Rinse and drain the cooked lentils.');
INSERT INTO "substitute_steps" VALUES(36,2,53,'Peel and chop the red onion. Rinse and drain cooked beans and sweetcorn. Heat the oil in a saucepan and cook the red onion for 5 minutes.');
INSERT INTO "substitute_steps" VALUES(37,2,24,'Add the unsweetened oat drink and heat slowly while stirring. Reduce to very low heat as soon as the liquid begins to boil. Oat drink can foam, so do not fill the saucepan to the rim.');
INSERT INTO "substitute_steps" VALUES(38,2,24,'Put oats, unsweetened oat drink, salt and the first half of the apple in a heavy-based saucepan. Heat over medium heat while stirring.');
INSERT INTO "substitute_steps" VALUES(39,1,24,'Whisk flour, unsweetened oat drink, egg and salt into a smooth batter without lumps. Leave to rest for 10 minutes.');
INSERT INTO "substitute_steps" VALUES(40,3,53,'Peel and thinly slice the red onions. Cook in the bacon fat over medium heat for 12–15 minutes until soft and golden. Stir often and lower the heat if they darken.');
INSERT INTO "substitute_steps" VALUES(41,2,24,'Heat the unsweetened oat drink in a small saucepan. Mash the potatoes, gradually stir in butter and hot unsweetened oat drink and add salt and pepper.');
INSERT INTO "substitute_steps" VALUES(42,2,53,'Peel and chop the red onion. Peel and finely dice the carrots. Heat the oil in a saucepan and cook the vegetables for 5 minutes.');
INSERT INTO "substitute_steps" VALUES(43,4,24,'Whisk together eggs, unsweetened oat drink, salt and pepper. Stir in cheese and pour over the filling so it flows between the pieces.');
INSERT INTO "substitute_steps" VALUES(44,3,24,'Whisk eggs with unsweetened oat drink, salt, pepper and nutmeg. Stir in cheese. Spread the cooked vegetables in the pastry case and pour over the egg mixture.');
INSERT INTO "substitute_steps" VALUES(45,2,32,'Mix tomato passata with oil, oregano and salt. Clean and thinly slice the mushrooms. Cut ham into strips and measure the grated cheese.');
INSERT INTO "substitute_steps" VALUES(45,3,32,'Spread a thin layer of sauce on the base, leaving a border. Arrange ham, mushrooms and grated cheese evenly. Avoid a thick topping that makes the centre wet.');
INSERT INTO "substitute_steps" VALUES(46,2,140,'Spread a thin layer of tomato passata over the dough. Drain the mozzarella thoroughly, tear into small pieces and spread with oregano and ham over the dough. Leave a narrow border along one long side.');
INSERT INTO "substitute_steps" VALUES(47,1,24,'Gently melt the butter in a saucepan. Add unsweetened oat drink and check the mixture is only lukewarm, no more than about 37 °C. Crumble yeast into a bowl and stir in the warm liquid until dissolved.');
INSERT INTO "substitute_steps" VALUES(48,1,53,'Peel and chop the red onion. Rinse and deseed the pepper, then finely dice it. Rinse and drain the cooked beans.');
INSERT INTO "substitute_steps" VALUES(49,1,53,'Heat a conventional oven to 200 °C. Peel and chop the red onion. Rinse and drain the cooked beans.');
INSERT INTO "substitute_steps" VALUES(50,2,16,'Cut the turkey breast into thin even slices on a separate board, then wash hands and utensils. Heat the oil, season the turkey breast with salt and pepper and fry for 8–12 minutes until fully cooked and at least 75 °C. Transfer to a clean plate.');
INSERT INTO "substitute_steps" VALUES(51,2,149,'Spread a thin layer of soft coconut oil on the outside of the bread. Spread a little mustard on the inside of each base.');
INSERT INTO "substitute_steps" VALUES(52,1,4,'Peel and very finely chop the onion. Thoroughly drain tuna and sweetcorn. Rinse and slice the cucumber. Squeeze the lemon juice. Chop the onion especially finely when it is served raw.');
INSERT INTO "substitute_steps" VALUES(53,2,137,'Mix both measured amounts of creme fraiche with curry powder, salt and pepper for the dressing. Rinse and finely snip the chives.');
INSERT INTO "substitute_steps" VALUES(54,2,16,'Cut the turkey breast into small even cubes on a separate board, then wash hands and utensils. Heat the oil and fry the turkey breast for 8–12 minutes with half the salt. Check for at least 75 °C in the centre. Spread on a clean plate to cool slightly.');
INSERT INTO "substitute_steps" VALUES(55,2,4,'Peel and finely chop the onion. Rinse cucumber, tomato and parsley. Finely dice cucumber and tomato and chop the parsley. Rinse and drain the cooked chickpeas. Chop the onion especially finely when it is served raw.');
INSERT INTO "substitute_steps" VALUES(56,2,4,'Peel and chop the onion. Rinse vegetables and parsley. Remove pepper seeds and finely dice tomato, cucumber and pepper. Chop the parsley. Chop the onion especially finely when it is served raw.');
INSERT INTO "substitute_steps" VALUES(57,1,4,'Peel and very thinly slice the onion. Rinse tomato and cucumber and cut into bite-size pieces. Drain the olives. Chop the onion especially finely when it is served raw.');
INSERT INTO "substitute_steps" VALUES(58,1,53,'Peel and chop the red onion. Peel and finely dice the carrots. Rinse lentils in a fine sieve.');
INSERT INTO "substitute_steps" VALUES(59,1,53,'Peel and chop the red onion. Peel potatoes, carrots and celeriac and cut into small even cubes. Split leeks lengthways, rinse between the layers and cut into rings. Rinse pearl barley in a sieve.');
INSERT INTO "substitute_steps" VALUES(60,1,53,'Peel and chop the red onion. Peel carrots, potatoes and ginger. Finely dice the root vegetables and finely chop the ginger.');
INSERT INTO "substitute_steps" VALUES(61,1,53,'Peel and chop the red onion. Peel and finely dice the potatoes. Rinse the broccoli, cut small florets and peel the thick stalk before dicing it.');
INSERT INTO "substitute_steps" VALUES(62,1,53,'Peel and chop red onion and garlic. Peel the carrots; rinse celery and courgette. Finely dice all vegetables. Rinse and drain the cooked beans.');
INSERT INTO "substitute_steps" VALUES(63,3,24,'Mix unsweetened oat drink, cooking cream, nutmeg, salt and pepper. Pour evenly over the potatoes and press gently with a spoon to moisten the layers.');
INSERT INTO "substitute_steps" VALUES(64,1,53,'Heat a conventional oven to 190 °C. Peel and chop the red onion. Clean and slice the mushrooms. Rinse, deseed and dice the pepper.');
INSERT INTO "substitute_steps" VALUES(65,2,53,'Peel and chop the red onions. Heat the oil in a saucepan and cook for 5 minutes until soft.');
INSERT INTO "substitute_steps" VALUES(66,1,53,'Peel the red onions and cut into strips. Clean and quarter the mushrooms. Pat the meat dry with kitchen paper.');
INSERT INTO "substitute_steps" VALUES(67,1,53,'Heat a conventional oven to 190 °C. Peel and chop red onion and garlic. Heat the oil in a saucepan and cook the red onion for 5 minutes. Add garlic for 30 seconds.');
INSERT INTO "substitute_steps" VALUES(69,3,223,'Check the coalfish for bones. Put on the leek sauce, add remaining salt and lemon slices. Bake at 190 °C for about 15–20 minutes, depending on thickness, until hot throughout and easy to flake.');
INSERT INTO "substitute_steps" VALUES(70,4,24,'Melt the butter in a saucepan and stir in flour. Gradually whisk in unsweetened oat drink and reserved cooking water until lightly creamy. Simmer for 5 minutes while stirring.');
INSERT INTO "substitute_steps" VALUES(71,2,53,'Peel and chop the red onions. Dice the ham. Heat about two-thirds of the oil in a large frying pan and cook potatoes for 10–15 minutes until tender and golden.');
INSERT INTO "substitute_steps" VALUES(72,1,53,'Peel and finely chop red onion and garlic. Clean and slice the mushrooms. Grate the Parmesan. Bring about 300 ml water per serving to the boil with stock powder and keep warm over low heat.');
INSERT INTO "substitute_steps" VALUES(73,1,53,'Peel and chop the red onion. Clean and slice the mushrooms. Rinse pearl barley and fresh spinach; frozen spinach can be added later without thawing.');
INSERT INTO "substitute_steps" VALUES(74,1,53,'Peel and grate the red onion. Peel potatoes and carrots and coarsely grate them. Squeeze liquid from the grated potatoes in a clean tea towel so the mixture is not watery.');
INSERT INTO "substitute_steps" VALUES(75,1,53,'Peel and chop red onion and garlic. Rinse the cauliflower, remove leaves and cut into small florets. Rinse and drain the cooked chickpeas. Cook the rice according to the packet.');
INSERT INTO "substitute_steps" VALUES(77,2,53,'Peel and chop the red onion. Rinse and drain the cooked lentils. Heat the remaining oil in a saucepan and cook red onion for 5 minutes.');
INSERT INTO "substitute_steps" VALUES(78,2,53,'Peel and chop the red onion. Heat the oil in a saucepan and cook red onion for 5 minutes.');
INSERT INTO "substitute_steps" VALUES(79,1,53,'Peel and chop red onion and garlic. Rinse and deseed the pepper and cut into small cubes.');
INSERT INTO "substitute_steps" VALUES(80,2,53,'Peel and thinly slice the red onions. Heat half the oil in a large frying pan and cook red onion over medium heat for 8 minutes until soft. Fold in potato slices for 2 minutes.');
INSERT INTO "substitute_steps" VALUES(81,1,53,'Peel and chop the red onion. Remove outer cabbage leaves and the tough core, then finely shred the cabbage. Peel potatoes and carrots and finely dice them.');
INSERT INTO "substitute_steps" VALUES(82,1,53,'Peel and grate the red onion. Mix minced meat with red onion, egg, oats, about one-sixth of the milk, half the salt and pepper. Refrigerate for 10 minutes. Reserve the remaining milk for the cabbage sauce.');
INSERT INTO "substitute_steps" VALUES(83,1,53,'Peel and chop the red onion. Peel and finely dice potatoes and carrots. Thoroughly rinse fresh kale, remove coarse stalks and finely chop the leaves. Frozen chopped kale can be used without thawing.');
INSERT INTO "substitute_steps" VALUES(84,1,53,'Peel and chop the red onion. Peel and finely dice carrots and celeriac. Split leeks lengthways, rinse between the layers and slice into rings. Rinse split peas thoroughly.');
INSERT INTO "substitute_steps" VALUES(85,1,53,'Peel and chop the red onion. Peel and finely dice carrots and celeriac. Rinse leeks thoroughly between the layers and cut into rings. Rinse the pearl barley.');
INSERT INTO "substitute_steps" VALUES(86,3,24,'Melt the butter in a saucepan and stir in flour. Gradually whisk in unsweetened oat drink. Add reserved cooking water until the sauce is thick but stirrable. Simmer for 5 minutes while stirring.');
INSERT INTO "substitute_steps" VALUES(87,2,4,'Peel and very finely chop the onion. Rinse and snip chives. Mix creme fraiche, mayonnaise, mustard, salt and pepper, then fold in chopped herbs and onion. Chop the onion especially finely when it is served raw.');
INSERT INTO "substitute_steps" VALUES(88,2,223,'Check the coalfish fillets for bones and pat dry with kitchen paper. Mix flour, remaining salt and pepper on a plate and lightly coat the fillets.');
INSERT INTO "substitute_steps" VALUES(88,3,223,'Melt about two-thirds of the butter in a frying pan over medium heat. Add coalfish when the butter foams gently. Fry for about 4–6 minutes per side, depending on thickness, until hot throughout and easy to flake. Turn carefully with a wide spatula.');
INSERT INTO "substitute_steps" VALUES(89,1,53,'Peel and finely grate the red onion. Drain tuna thoroughly and flake with a fork. Mix with red onion, egg, breadcrumbs, half the salt and pepper into a firm mixture. Refrigerate for 10 minutes.');
INSERT INTO "substitute_steps" VALUES(90,2,227,'Cook the breaded fish fillets using the oven temperature and time on the packet, typically about 15–25 minutes. Arrange in one layer and turn if instructed. The coating must be crisp and the fish hot and firm in the centre.');
INSERT INTO "substitute_steps" VALUES(91,1,53,'Peel and chop red onion and garlic. Peel carrots and rinse celery. Finely dice the vegetables. Rinse lentils in a fine sieve.');
INSERT INTO "substitute_steps" VALUES(93,1,53,'Peel and chop the red onion. Peel sweet potatoes and cut into small cubes about 2 cm wide. Rinse and drain cooked chickpeas; rinse fresh spinach.');
INSERT INTO "substitute_steps" VALUES(94,2,16,'Cut the turkey breast into thin even strips on a separate board, then wash hands and utensils. Heat the oil in a large frying pan and cook the turkey breast for 8–12 minutes. Turn regularly; it must be fully cooked and at least 75 °C in the centre.');
INSERT INTO "substitute_steps" VALUES(95,3,16,'Cut the turkey breast into even strips on a separate board, then wash hands and utensils. Heat the oil in a frying pan. Fry turkey breast for 8–12 minutes, turning, until fully cooked and at least 75 °C.');
INSERT INTO "substitute_steps" VALUES(96,4,138,'Toss hot pasta with cream cheese and a little reserved cooking water until a smooth sauce forms. Fold in fully cooked beans and tomatoes, sprinkle with Parmesan and serve immediately.');
INSERT INTO "substitute_steps" VALUES(97,1,53,'Peel and chop the red onion. Rinse fresh spinach; frozen spinach can be added directly to the sauce later. Squeeze lemon juice. Cook pasta according to the packet and reserve some cooking water.');
INSERT INTO "substitute_steps" VALUES(97,2,38,'Check the cod for bones and cut into bite-size cubes. Wash hands and utensils after raw fish. Heat the oil in a wide saucepan and cook onion for 5 minutes. Add fish cubes and turn gently for 1 minute.');
INSERT INTO "substitute_steps" VALUES(97,3,38,'Add cooking cream and simmer gently for about 5–8 minutes, depending on fish-piece size. The fish must be hot throughout and easy to flake. Avoid vigorous stirring so the lean pieces hold their shape.');
INSERT INTO "substitute_steps" VALUES(98,1,53,'Peel and very finely chop the red onion. Thoroughly rinse and drain cooked beans. Mash in a bowl with a fork, leaving some larger pieces if preferred.');
INSERT INTO "substitute_steps" VALUES(99,1,53,'Peel and chop red onion and garlic. Rinse aubergine, courgette and pepper. Remove pepper seeds and cut all vegetables into even bite-size cubes.');
INSERT INTO "substitute_steps" VALUES(100,2,210,'Finely dice the ham. Heat a large non-stick frying pan over medium heat and warm the ham for 2–3 minutes with a little pasta cooking water to prevent sticking. Turn off the heat under the pan.');
INSERT INTO "substitutes" VALUES(1,2,'Use pasta only after explicitly approving a different ingredient. Use the same dry weight for grains and follow the selected packet water quantity and cooking time separately. Bread is warmed according to its packet. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(2,1,'Use rice only after explicitly approving a different ingredient. Use the same dry weight for grains and follow the selected packet water quantity and cooking time separately. Bread is warmed according to its packet. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(4,53,'Use red onion only after explicitly approving a different ingredient. Use the same weight. Peel and chop finely; a regular onion can taste sharper when raw. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(7,46,'Use green peas only after explicitly approving a different ingredient. Use the same edible weight, cut even pieces and check tenderness. Different vegetables can need different cooking times; frozen vegetables follow their packet. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(15,16,'Use turkey breast only after explicitly approving a different ingredient. Use the same weight, cut even pieces and cook fully to at least 75 °C in the thickest part. Allow extra time for thick pieces. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(16,15,'Use chicken breast only after explicitly approving a different ingredient. Use the same weight of the specified edible cut. Fully cook minced meat and poultry to at least 75 °C; cook fish gently until hot throughout and flaky. Thickness changes the cooking time. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(17,18,'Use minced pork only after explicitly approving a different ingredient. Use the same weight of the specified edible cut. Fully cook minced meat and poultry to at least 75 °C; cook fish gently until hot throughout and flaky. Thickness changes the cooking time. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(17,54,'Use minced chicken only after explicitly approving a different ingredient. Use the same weight of the specified edible cut. Fully cook minced meat and poultry to at least 75 °C; cook fish gently until hot throughout and flaky. Thickness changes the cooking time. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(18,17,'Use minced beef only after explicitly approving a different ingredient. Use the same weight of the specified edible cut. Fully cook minced meat and poultry to at least 75 °C; cook fish gently until hot throughout and flaky. Thickness changes the cooking time. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(20,21,'Use cooked kidney beans only after explicitly approving a different ingredient. Use the same drained ready-to-eat weight, rinse and heat thoroughly. Do not put raw dried beans or chickpeas directly into a cooked-bean recipe. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(21,20,'Use cooked chickpeas only after explicitly approving a different ingredient. Use the same drained ready-to-eat weight, rinse and heat thoroughly. Do not put raw dried beans or chickpeas directly into a cooked-bean recipe. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(23,24,'Use oat drink only after explicitly approving a different ingredient. Use the same volume. Choose an unsweetened drink for savoury dishes and stir regularly in hot sauces. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(24,23,'Use milk only after explicitly approving a different ingredient. Use the same volume. Choose an unsweetened drink for savoury dishes and stir regularly in hot sauces. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(25,26,'Use cooking cream only after explicitly approving a different ingredient. Use the same weight for cheese or the same volume for cream. Flavour, salt and melting can differ; yoghurt in hot dishes must be stirred in gently without boiling. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(26,25,'Use cream only after explicitly approving a different ingredient. Use the same weight for cheese or the same volume for cream. Flavour, salt and melting can differ; yoghurt in hot dishes must be stirred in gently without boiling. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(28,29,'Use olive oil only after explicitly approving a different ingredient. Use the same amount in the same unit. For cooking oil, use moderate heat and do not let it smoke. Dressings and sauces can change flavour and thickness. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(29,28,'Use rapeseed oil only after explicitly approving a different ingredient. Use the same amount in the same unit. For cooking oil, use moderate heat and do not let it smoke. Dressings and sauces can change flavour and thickness. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(46,7,'Use broccoli only after explicitly approving a different ingredient. Use the same edible weight, cut even pieces and check tenderness. Different vegetables can need different cooking times; frozen vegetables follow their packet. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(53,4,'Use onion only after explicitly approving a different ingredient. Use the same weight. Peel and chop finely; a regular onion can taste sharper when raw. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(54,17,'Use minced beef only after explicitly approving a different ingredient. Use the same weight of the specified edible cut. Fully cook minced meat and poultry to at least 75 °C; cook fish gently until hot throughout and flaky. Thickness changes the cooking time. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(7,57,'Use cauliflower only after explicitly approving a different ingredient. Use the same edible weight, cut even pieces and check tenderness. Different vegetables can need different cooking times; frozen vegetables follow their packet. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
INSERT INTO "substitutes" VALUES(57,7,'Use broccoli only after explicitly approving a different ingredient. Use the same edible weight, cut even pieces and check tenderness. Different vegetables can need different cooking times; frozen vegetables follow their packet. A recipe replacement also requires its separately supported cooking instructions; it is never a direct translation.');
