BEGIN TRANSACTION;
CREATE TABLE aliases(ingredient_id INTEGER NOT NULL REFERENCES ingredients(id),name TEXT NOT NULL,search TEXT NOT NULL,PRIMARY KEY(ingredient_id,search));
CREATE TABLE cooking_steps(
    recipe_id INTEGER NOT NULL REFERENCES recipes(id),number INTEGER NOT NULL CHECK(number>0),
    line INTEGER NOT NULL DEFAULT 0 CHECK(line BETWEEN 0 AND 32),text TEXT NOT NULL CHECK(length(text)>0),
    PRIMARY KEY(recipe_id,number));
CREATE TABLE ingredients(id INTEGER PRIMARY KEY,name TEXT NOT NULL,danish_name TEXT NOT NULL,unit TEXT NOT NULL,category TEXT NOT NULL);
CREATE TABLE metadata(name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE name_suggestions(search TEXT NOT NULL,to_id INTEGER NOT NULL REFERENCES ingredients(id),advice TEXT NOT NULL,PRIMARY KEY(search,to_id));
CREATE TABLE recipe_ingredients(
    recipe_id INTEGER NOT NULL REFERENCES recipes(id),number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 32),
    ingredient_id INTEGER NOT NULL REFERENCES ingredients(id),amount REAL NOT NULL CHECK(amount>0),
    PRIMARY KEY(recipe_id,number));
CREATE TABLE recipe_substitutes(
    recipe_id INTEGER NOT NULL,line INTEGER NOT NULL,replacement_id INTEGER NOT NULL REFERENCES ingredients(id),
    advice TEXT NOT NULL,PRIMARY KEY(recipe_id,line,replacement_id),
    FOREIGN KEY(recipe_id,line) REFERENCES recipe_ingredients(recipe_id,number));
CREATE TABLE recipes(
    id INTEGER PRIMARY KEY,name TEXT NOT NULL,search TEXT NOT NULL,description TEXT NOT NULL,
    servings INTEGER NOT NULL CHECK(servings BETWEEN 1 AND 20),
    preparation_minutes INTEGER NOT NULL CHECK(preparation_minutes>=0),cooking_minutes INTEGER NOT NULL CHECK(cooking_minutes>=0), danish_name TEXT NOT NULL DEFAULT "", danish_description TEXT NOT NULL DEFAULT "");
CREATE TABLE substitute_steps(
    recipe_id INTEGER NOT NULL,number INTEGER NOT NULL,replacement_id INTEGER NOT NULL REFERENCES ingredients(id),
    text TEXT NOT NULL CHECK(length(text)>0),PRIMARY KEY(recipe_id,number,replacement_id),
    FOREIGN KEY(recipe_id,number) REFERENCES cooking_steps(recipe_id,number));
CREATE TABLE substitutes(from_id INTEGER NOT NULL REFERENCES ingredients(id),to_id INTEGER NOT NULL REFERENCES ingredients(id),advice TEXT NOT NULL,PRIMARY KEY(from_id,to_id));
CREATE INDEX index_1 ON aliases(search);
CREATE INDEX index_2 ON recipes(search);
COMMIT;
